
const $=s=>document.querySelector(s), money=n=>new Intl.NumberFormat('ru-RU').format(Number(n)||0)+' so‘m', esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let D=null, me=null, currentTab='dashboard', reportAreas=[];
let adminRealtimeSource=null,adminRealtimeTimer=null,adminRealtimeBusy=false,adminRealtimePending=false,adminRealtimeState='waiting';
function setLiveState(state){adminRealtimeState=state;const el=document.getElementById('liveBadge');if(!el)return;el.className='live-badge '+(state==='live'?'':state);el.textContent=state==='live'?'LIVE • Online':state==='offline'?'Ulanish tiklanmoqda':'LIVE • Kutilmoqda'}
function adminIsEditing(){const ae=document.activeElement,tag=ae?.tagName;return Boolean(document.querySelector('#productModalRoot .product-modal')||['INPUT','TEXTAREA','SELECT'].includes(tag))}
async function realtimeAdminRefresh(){
 if(!me||adminRealtimeBusy)return;
 if(adminIsEditing()){adminRealtimePending=true;return}
 adminRealtimeBusy=true;adminRealtimePending=false;
 try{D=await api('/api/admin/dashboard');renderApp();setLiveState('live')}catch(e){if(e.message?.includes('Kirish')){me=null;renderLogin()}else console.error('Realtime admin refresh',e)}finally{adminRealtimeBusy=false}
}
function scheduleAdminRealtime(){clearTimeout(adminRealtimeTimer);adminRealtimeTimer=setTimeout(realtimeAdminRefresh,140)}
function initAdminRealtime(){if(!window.EventSource||adminRealtimeSource)return;adminRealtimeSource=new EventSource('/api/events');adminRealtimeSource.addEventListener('ready',()=>setLiveState('live'));adminRealtimeSource.addEventListener('update',scheduleAdminRealtime);adminRealtimeSource.onopen=()=>setLiveState('live');adminRealtimeSource.onerror=()=>setLiveState('offline')}
document.addEventListener('focusout',()=>{if(adminRealtimePending)setTimeout(()=>{if(!adminIsEditing())realtimeAdminRefresh()},80)});
async function api(url,opt={}){const r=await fetch(url,{...opt,headers:{'Content-Type':'application/json',...(opt.headers||{})}});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Xatolik');return d}
async function boot(){try{me=await api('/api/admin/me');await refresh();}catch{renderLogin()}}
function renderLogin(){document.getElementById('app').innerHTML=`<div class="panel login"><div style="display:flex;align-items:center;gap:16px"><img src="logo.png" class="logo-admin"><div><span class="eyebrow">ZARBULOQ.UZ</span><h1>IMOM OTA BARAKA</h1><p>Boshqaruv markaziga kiring.</p></div></div><form onsubmit="login(event)"><input name="username" placeholder="Foydalanuvchi nomi" required><input name="password" type="password" placeholder="Parol" required><button class="btn primary">Kirish</button></form></div>`}
async function login(e){e.preventDefault();const f=new FormData(e.currentTarget);try{me=await api('/api/admin/login',{method:'POST',body:JSON.stringify({username:f.get('username'),password:f.get('password')})});await refresh()}catch(err){alert(err.message)}}
async function logout(){await api('/api/admin/logout',{method:'POST'});renderLogin()}
async function refresh(){D=await api('/api/admin/dashboard');renderApp()}
function renderApp(){const s=D.stats, role=D.role||me?.role||'admin';document.getElementById('app').innerHTML=`<div class="admin-wrap"><div class="admin-top"><div class="admin-brand"><img src="${D.logo||'logo.png'}" class="logo-admin"><div><span class="eyebrow">ZARBULOQ.UZ</span><h1>IMOM OTA BARAKA</h1><p>Original e-commerce boshqaruv markazi • <span class="role-badge">${esc(role)}</span></p></div></div><div class="admin-actions"><span id="liveBadge" class="live-badge waiting">LIVE • Kutilmoqda</span><a class="btn ghost" href="/" target="_blank">← Do‘konga</a><button class="btn ghost" onclick="refresh()">↻ Yangilash</button><button class="btn danger" onclick="logout()">Chiqish</button></div></div>
<div class="stats-grid"><div class="stat"><span>Barcha buyurtma</span><b>${s.orders}</b></div><div class="stat"><span>Bugun</span><b>${s.today}</b></div><div class="stat"><span>Oy</span><b>${s.month}</b></div><div class="stat"><span>Tushum</span><b>${money(s.revenue)}</b></div><div class="stat"><span>Foyda</span><b>${money(s.profit)}</b></div><div class="stat"><span>O‘rtacha chek</span><b>${money(s.avg)}</b></div><div class="stat"><span>Jarayonda</span><b>${s.pending}</b></div><div class="stat"><span>Kam qoldiq ≤5</span><b>${s.lowStock}</b></div></div>
<div class="tabs">${[['dashboard','Dashboard'],['orders',`Buyurtmalar${(D.orders||[]).filter(o=>o.status==='new').length?` <span class="tab-count">${(D.orders||[]).filter(o=>o.status==='new').length}</span>`:''}`],['requests',`Mahsulot so‘rovlari${(D.productRequests||[]).filter(r=>r.status==='new').length?' • '+(D.productRequests||[]).filter(r=>r.status==='new').length:''}`],['chats',`LIVE chat${(D.chats||[]).reduce((s,c)=>s+Number(c.unreadAdmin||0),0)?' • '+(D.chats||[]).reduce((s,c)=>s+Number(c.unreadAdmin||0),0):''}`],['products','Mahsulotlar'],['warehouse','Ombor'],['slides','Bosh sahifa slayderi'],['customers','Mijozlar'],['finance','FINANS'],['reports','Hisobotlar'],['promos','Promo kodlar'],['areas','Hududlar'],['pages','Sahifalar / SEO'],['audit','Audit / Backup']].map(x=>`<button class="tab ${currentTab===x[0]?'active':''}" onclick="tab('${x[0]}')">${x[1]}</button>`).join('')}</div>
<div id="pane"></div></div>`;renderPane();setLiveState(adminRealtimeState)}
function tab(t){currentTab=t;renderApp()}
function renderPane(){const p=$('#pane');if(currentTab==='dashboard'){p.innerHTML=dashboardPane();setTimeout(renderDashboardAnalytics,0);}if(currentTab==='orders')p.innerHTML=ordersPane();if(currentTab==='requests')p.innerHTML=requestsPane();if(currentTab==='chats')p.innerHTML=chatsPane();if(currentTab==='products')p.innerHTML=productsPane();if(currentTab==='warehouse')p.innerHTML=warehousePane();if(currentTab==='slides')p.innerHTML=slidesPane();if(currentTab==='customers')p.innerHTML=customersPane();if(currentTab==='finance'){p.innerHTML=financePane();setTimeout(loadFinance,0)}if(currentTab==='reports')p.innerHTML=reportsPane();if(currentTab==='promos')p.innerHTML=promosPane();if(currentTab==='areas')p.innerHTML=areasPane();if(currentTab==='pages')p.innerHTML=pagesPane();if(currentTab==='audit')p.innerHTML=auditPane()}
function dashAnalyticsRows(){return D.analytics?.monthly||[]}
function dashProducts(){return D.analytics?.products||[]}
function dashboardPane(){const now=new Date(),years=D.analytics?.years||[now.getFullYear()],months=['Barchasi','Yanvar','Fevral','Mart','Aprel','May','Iyun','Iyul','Avgust','Sentabr','Oktabr','Noyabr','Dekabr'];return `<div class="panel"><div class="inv-head"><div class="inv-title"><h2>Dashboard hisoboti</h2><p>Ombor, savdo, zayavka, topshirish va prognoz — mahsulot, oy va yil kesimida.</p></div></div><div class="dash-filterbar"><label>Mahsulot<select id="dashProduct" onchange="renderDashboardAnalytics()"><option value="all">Barchasi</option>${dashProducts().map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><label>Yil<select id="dashYear" onchange="renderDashboardAnalytics()"><option value="all">Barchasi</option>${years.map(y=>`<option value="${y}" ${Number(y)===now.getFullYear()?'selected':''}>${y}</option>`).join('')}</select></label><label>Oy<select id="dashMonth" onchange="renderDashboardAnalytics()">${months.map((m,i)=>`<option value="${i===0?'all':String(i).padStart(2,'0')}">${m}</option>`).join('')}</select></label></div><div id="dashAnalyticsRoot"></div></div>`}
function dashboardFilteredRows(){const pid=$('#dashProduct')?.value||'all',year=$('#dashYear')?.value||'all',month=$('#dashMonth')?.value||'all';return dashAnalyticsRows().filter(r=>(pid==='all'||String(r.productId)===pid)&&(year==='all'||String(r.month).slice(0,4)===year)&&(month==='all'||String(r.month).slice(5,7)===month))}
function dashSum(rows,key){return rows.reduce((a,r)=>a+Number(r[key]||0),0)}
function renderDashboardAnalytics(){const root=$('#dashAnalyticsRoot');if(!root)return;const rows=dashboardFilteredRows(),pid=$('#dashProduct')?.value||'all',year=$('#dashYear')?.value||'all';const prods=pid==='all'?dashProducts():dashProducts().filter(p=>String(p.id)===pid);const stockQty=prods.reduce((a,p)=>a+Number(p.stock||0),0),stockValue=prods.reduce((a,p)=>a+Number(p.stock||0)*Number(p.cost||0),0),soldQty=dashSum(rows,'soldQty'),soldAmount=dashSum(rows,'soldAmount'),appQty=dashSum(rows,'applicationQty'),appAmount=dashSum(rows,'applicationAmount'),deliveryQty=dashSum(rows,'deliveryQty'),deliveryAmount=dashSum(rows,'deliveryAmount'),doneQty=dashSum(rows,'doneQty'),doneAmount=dashSum(rows,'doneAmount'),acceptedQty=dashSum(rows,'acceptedQty'),cancelledQty=dashSum(rows,'cancelledQty'),receivedQty=dashSum(rows,'receivedQty');const unitMap={};prods.forEach(p=>{const u=p.unit||'dona';unitMap[u]=unitMap[u]||{stock:0,value:0};unitMap[u].stock+=Number(p.stock||0);unitMap[u].value+=Number(p.stock||0)*Number(p.cost||0)});const months=Array.from({length:12},(_,i)=>String(i+1).padStart(2,'0'));const yr=year==='all'?String(new Date().getFullYear()):year;const monthly=months.map(m=>{const rr=dashAnalyticsRows().filter(r=>(pid==='all'||String(r.productId)===pid)&&String(r.month)===`${yr}-${m}`);return {month:m,qty:dashSum(rr,'soldQty'),amount:dashSum(rr,'soldAmount'),application:dashSum(rr,'applicationQty')}});const recent=monthly.map(x=>x.qty).filter((_,i)=>i<new Date().getMonth()+1);const tail=recent.slice(-3),avg=tail.length?tail.reduce((a,b)=>a+b,0)/tail.length:0;const trend=tail.length>=2?(tail[tail.length-1]-tail[0])/(tail.length-1):0;const forecast=Math.max(0,Math.round(avg+trend));const product=pid==='all'?null:dashProducts().find(p=>String(p.id)===pid);root.innerHTML=`<div class="dash-kpis"><div class="dash-kpi"><span>Ombordagi qoldiq</span><b>${stockQty}</b></div><div class="dash-kpi"><span>Ombor tannarx summasi</span><b>${money(stockValue)}</b></div><div class="dash-kpi"><span>Sotilgan mahsulot</span><b>${soldQty}</b></div><div class="dash-kpi"><span>Sotilgan summa</span><b>${money(soldAmount)}</b></div><div class="dash-kpi"><span>Zayavka miqdori</span><b>${appQty}</b></div><div class="dash-kpi"><span>Zayavka summasi</span><b>${money(appAmount)}</b></div></div><div class="dash-section-grid"><div class="panel chart-card"><h3>${yr} — oylar bo‘yicha savdo</h3><div style="overflow:auto"><table class="dash-month-table"><thead><tr><th>Oy</th><th>Sotilgan</th><th>Sotuv summasi</th><th>Zayavka</th></tr></thead><tbody>${monthly.map((x,i)=>`<tr><td>${['Yan','Fev','Mar','Apr','May','Iyun','Iyul','Avg','Sen','Okt','Noy','Dek'][i]}</td><td>${x.qty}</td><td>${money(x.amount)}</td><td>${x.application}</td></tr>`).join('')}</tbody></table></div></div><div><div class="dash-forecast"><small>Keyingi oy savdo prognozi</small><b>${forecast} ${product?.unit||'birlik'}</b><small>Oxirgi 3 oy o‘rtachasi va trend asosida taxminiy ko‘rsatkich.</small></div><div class="panel" style="margin-top:14px"><h3>Holatlar</h3><div class="dash-status-grid"><div class="dash-status"><span>Yetkazilmoqda</span><b>${deliveryQty}</b><small>${money(deliveryAmount)}</small></div><div class="dash-status"><span>Yakunlandi</span><b>${doneQty}</b><small>${money(doneAmount)}</small></div><div class="dash-status"><span>Qabul qilindi</span><b>${acceptedQty}</b></div><div class="dash-status"><span>Bekor qilindi</span><b>${cancelledQty}</b></div></div></div></div></div><div class="panel"><h3>Ombor — o‘lchov birligi bo‘yicha</h3><div class="dash-unit-grid">${Object.entries(unitMap).map(([u,v])=>`<div class="dash-unit-card"><span>${esc(u)}</span><b>${v.stock}</b><small>${money(v.value)}</small></div>`).join('')||'<p class="muted">Ma’lumot yo‘q</p>'}</div></div><div class="panel"><h3>Qo‘shimcha natijalar</h3><div class="dash-product-summary"><div><span>Qabul qilingan kirim</span><b>${receivedQty}</b></div><div><span>Yetkazilayotgan summa</span><b>${money(deliveryAmount)}</b></div><div><span>Yakunlangan summa</span><b>${money(doneAmount)}</b></div><div><span>Bekor qilingan miqdor</span><b>${cancelledQty}</b></div></div></div>`}
function ordersPane(){return `<div class="panel"><div class="toolbar"><input id="orderSearch" class="grow" placeholder="Buyurtma, mijoz yoki telefon bo‘yicha qidirish" oninput="filterOrders()"><select id="orderStatus" onchange="filterOrders()"><option value="">Barcha statuslar</option><option value="new">Yangi</option><option value="accepted">Qabul qilindi</option><option value="delivery">Yetkazilmoqda</option><option value="done">Yakunlandi</option><option value="cancelled">Bekor qilindi</option></select></div><div class="table"><table><thead><tr><th>Buyurtma</th><th>Mijoz</th><th>Hudud / Manzil</th><th>Mahsulot</th><th>Jami</th><th>Sana</th><th>Status</th></tr></thead><tbody id="ordersBody">${orderRows(D.orders)}</tbody></table></div></div>`}
function orderRows(arr){return arr.map(o=>`<tr data-search="${esc((o.orderId+' '+o.customer?.name+' '+o.customer?.phone).toLowerCase())}" data-status="${o.status}"><td><b>${esc(o.orderId)}</b><br><small>${esc(o.customer?.payment||'')}</small></td><td>${esc(o.customer?.name||'')}<br><a href="tel:${esc(o.customer?.phone||'')}">${esc(o.customer?.phone||'')}</a></td><td><b>${esc(o.customer?.area||'')}</b><br>${esc(o.customer?.address||'')}<br><small>${esc(o.customer?.deliverySlot||'')}</small>${o.customer?.lat&&o.customer?.lng?`<br><a target="_blank" href="https://maps.google.com/?q=${o.customer.lat},${o.customer.lng}">📍 Xaritada ochish</a>`:''}</td><td>${(o.items||[]).map(i=>`${esc(i.name)} × ${i.qty}`).join('<br>')}</td><td><b>${money(o.total)}</b>${o.discount?`<br><small>−${money(o.discount)}</small>`:''}</td><td>${new Date(o.createdAt).toLocaleString('uz-UZ')}</td><td><select class="status-select" onchange="setStatus('${o.orderId}',this.value)">${[['new','🕓 Yangi'],['accepted','✅ Qabul qilindi'],['delivery','🚚 Yetkazilmoqda'],['done','📦 Yakunlandi'],['cancelled','❌ Bekor qilindi']].map(x=>`<option value="${x[0]}" ${o.status===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></td></tr>`).join('')}
function filterOrders(){const q=$('#orderSearch').value.toLowerCase(),st=$('#orderStatus').value;[...$('#ordersBody').children].forEach(tr=>tr.style.display=(!q||tr.dataset.search.includes(q))&&(!st||tr.dataset.status===st)?'':'none')}
async function setStatus(id,status){try{await api(`/api/admin/orders/${id}/status`,{method:'PATCH',body:JSON.stringify({status})});await refresh()}catch(e){alert(e.message)}}
function requestsPane(){const a=D.productRequests||[];return `<div class="panel"><div class="inv-head"><div class="inv-title"><h2>Mahsulot so‘rovlari</h2><p>Mijoz katalogdan topa olmagan mahsulotlar bo‘yicha so‘rovlar.</p></div><div class="inv-tools"><input id="reqSearch" placeholder="Mahsulot yoki telefon..." oninput="filterRequests()"><select id="reqStatus" onchange="filterRequests()"><option value="">Barcha statuslar</option><option value="new">Yangi</option><option value="working">Ko‘rib chiqilmoqda</option><option value="found">Topildi</option><option value="closed">Yopildi</option></select></div></div><div class="table"><table><thead><tr><th>Sana / №</th><th>Mahsulot</th><th>Mijoz</th><th>Rasm</th><th>Izoh</th><th>Status</th></tr></thead><tbody id="reqBody">${a.map(r=>`<tr class="req-row" data-search="${esc((r.productName+' '+r.phone+' '+(r.customerName||'')).toLowerCase())}" data-status="${esc(r.status||'new')}"><td>${new Date(r.createdAt).toLocaleString('uz-UZ')}<br><small>${esc(r.requestId)}</small></td><td><b>${esc(r.productName)}</b><br>${Number(r.qty||1)} dona</td><td>${esc(r.customerName||'—')}<br><a href="tel:${esc(r.phone)}">${esc(r.phone)}</a></td><td>${r.image?`<a href="${r.image}" target="_blank"><img class="inv-img" src="${r.image}"></a>`:'—'}</td><td>${esc(r.comment||'—')}</td><td><select class="status-select" onchange="setRequestStatus('${esc(r.requestId)}',this.value)">${[['new','Yangi'],['working','Ko‘rib chiqilmoqda'],['found','Topildi'],['closed','Yopildi']].map(x=>`<option value="${x[0]}" ${(r.status||'new')===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></td></tr>`).join('')||'<tr><td colspan="6">Hozircha so‘rov yo‘q.</td></tr>'}</tbody></table></div></div>`}
function filterRequests(){const q=($('#reqSearch')?.value||'').toLowerCase(),st=$('#reqStatus')?.value||'';document.querySelectorAll('.req-row').forEach(r=>r.style.display=(!q||r.dataset.search.includes(q))&&(!st||r.dataset.status===st)?'':'none')}
async function setRequestStatus(id,status){try{await api(`/api/admin/product-requests/${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify({status})});await refresh()}catch(e){alert(e.message)}}

let activeAdminChat='';
function chatsPane(){const chats=(D.chats||[]).slice().sort((a,b)=>String(b.updatedAt||'').localeCompare(String(a.updatedAt||'')));if(!activeAdminChat&&chats[0])activeAdminChat=chats[0].sessionId;const c=chats.find(x=>x.sessionId===activeAdminChat)||chats[0];return `<div class="admin-chat-layout"><div class="panel"><h2 style="margin-top:0">Mijozlar bilan LIVE chat</h2><p class="muted">Saytdagi “Aloqa” bo‘limidan kelgan xabarlar.</p><div class="admin-chat-list">${chats.map(x=>`<button class="admin-chat-item ${c?.sessionId===x.sessionId?'active':''}" onclick="openAdminChat('${esc(x.sessionId)}')"><b>${esc(x.name||'Noma’lum mijoz')}${Number(x.unreadAdmin||0)?` <span class="unread-pill">${Number(x.unreadAdmin||0)}</span>`:''}</b><span>${esc(x.phone||'Telefon kiritilmagan')}</span><small>${x.updatedAt?new Date(x.updatedAt).toLocaleString('uz-UZ'):''}</small></button>`).join('')||'<div class="notice">Hozircha chat yo‘q.</div>'}</div></div><div class="panel">${c?adminChatThread(c):'<div class="notice">Mijoz yozganda chat shu yerda chiqadi.</div>'}</div></div>`}
function adminChatThread(c){return `<div class="admin-chat-thread"><div><h3 style="margin:0">${esc(c.name||'Mijoz')}</h3><p class="muted" style="margin:4px 0 10px">${esc(c.phone||'Telefon kiritilmagan')} • ${esc(c.sessionId)}</p></div><div id="adminChatMessages" class="admin-chat-messages">${(c.messages||[]).map(m=>`<div class="admin-chat-msg ${m.from==='admin'?'admin':'customer'}">${esc(m.text)}<small>${m.from==='admin'?'Admin':'Mijoz'} • ${new Date(m.createdAt).toLocaleString('uz-UZ')}</small></div>`).join('')||'<div class="muted">Xabar yo‘q.</div>'}</div><form class="admin-chat-reply" onsubmit="sendAdminChat(event,'${esc(c.sessionId)}')"><input id="adminChatInput" maxlength="1200" placeholder="Javob yozing..." required><button class="btn primary">Yuborish</button></form></div>`}
async function openAdminChat(id){activeAdminChat=id;try{await api('/api/admin/chats/'+encodeURIComponent(id)+'/read',{method:'PATCH',body:'{}'});await refresh()}catch(e){console.error(e)}setTimeout(()=>{const b=$('#adminChatMessages');if(b)b.scrollTop=b.scrollHeight},30)}
async function sendAdminChat(e,id){e.preventDefault();const inp=$('#adminChatInput'),message=inp.value.trim();if(!message)return;const b=e.currentTarget.querySelector('button');b.disabled=true;try{await api('/api/admin/chats/'+encodeURIComponent(id)+'/send',{method:'POST',body:JSON.stringify({message})});inp.value='';await refresh();activeAdminChat=id;renderApp();setTimeout(()=>{const box=$('#adminChatMessages');if(box)box.scrollTop=box.scrollHeight},30)}catch(err){alert(err.message)}finally{b.disabled=false}}

function productsPane(){return `<div class="panel"><div class="inv-head"><div class="inv-title"><h2>Mahsulotlar</h2><p>Mahsulot kartochkalari, narxlar, tillar, birlik va rasmlarni boshqaring.</p></div><div class="inv-tools"><input id="invSearch" placeholder="Mahsulot nomi bo‘yicha qidirish..." oninput="filterInventory()"><select id="invCat" onchange="filterInventory()"><option value="">Barcha kategoriyalar</option>${D.categories.map(c=>`<option value="${c.id}">${esc(c.name?.uz||c.id)}</option>`).join('')}</select><button class="btn primary" onclick="createProductAndOpen()">+ Mahsulot qo‘shish</button></div></div><div class="inv-table-wrap"><table class="inv-table"><thead><tr><th>#</th><th>Rasm</th><th>Mahsulot nomi</th><th>Kategoriya</th><th>Sotuv narxi</th><th>Tannarx</th><th>Eski narx</th><th>Zaxira</th><th>Holat</th><th>Amallar</th></tr></thead><tbody id="invBody">${D.products.map((p,i)=>inventoryRow(p,i)).join('')}</tbody></table></div><div class="inv-foot"><span>Jami: ${D.products.length} ta mahsulot</span><span>1</span></div><div class="category-manager"><div class="category-head"><div><h3>Kategoriyalar</h3><p class="muted small">Yangi kategoriya qo‘shing yoki mavjud nomlarini o‘zgartiring.</p></div><button class="btn primary sm" onclick="addCategory()">+ Yangi kategoriya</button></div><div id="categoryRows">${D.categories.map((c,i)=>categoryRow(c,i)).join('')}</div><button class="btn ghost sm" onclick="saveCategories()">Kategoriyalarni saqlash</button></div></div><div id="productModalRoot"></div>`}
function categoryRow(c,i){return `<div class="category-row" data-i="${i}"><input class="cuz" value="${esc(c.name?.uz||'')}" placeholder="Nomi (UZ)"><input class="cru" value="${esc(c.name?.ru||'')}" placeholder="Nomi (RU)"><button class="btn danger sm" onclick="removeCategory(${i})">O‘chirish</button></div>`}
function addCategory(){const id='cat_'+Date.now();D.categories.push({id,icon:'',name:{uz:'Yangi kategoriya',ru:'Новая категория'}});renderPane()}
function removeCategory(i){const c=D.categories[i];if(!c)return;if(D.products.some(p=>p.cat===c.id)){alert('Bu kategoriyada mahsulot bor. Avval mahsulotlarni boshqa kategoriyaga o‘tkazing.');return}if(!confirm('Kategoriya o‘chirilsinmi?'))return;D.categories.splice(i,1);renderPane()}
async function saveCategories(){document.querySelectorAll('.category-row').forEach(r=>{const c=D.categories[Number(r.dataset.i)];if(!c)return;c.name=c.name||{};c.name.uz=r.querySelector('.cuz').value.trim()||'Kategoriya';c.name.ru=r.querySelector('.cru').value.trim()||c.name.uz});await saveSettings('Kategoriyalar saqlandi')}
function inventoryRow(p,i){const c=D.categories.find(x=>x.id===p.cat);const st=(p.badge||'Faol');const cls=/aksiya/i.test(st)?'sale':/yangi/i.test(st)?'new':'';return `<tr class="inv-row" data-name="${esc((p.name?.uz||'').toLowerCase())}" data-cat="${esc(p.cat||'')}"><td>${i+1}</td><td>${p.image?`<img class="inv-img" src="${p.image}" alt="">`:`<div class="inv-img-empty">Rasm yo‘q</div>`}</td><td class="inv-name">${esc(p.name?.uz||'')}</td><td><span class="inv-cat">${esc(c?.name?.uz||p.cat||'')}</span></td><td>${money(p.price)}</td><td>${money(p.cost||0)}</td><td>${p.oldPrice?money(p.oldPrice):'—'}</td><td>${Number(p.stock||0)}</td><td><span class="inv-status ${cls}">${esc(st)}</span></td><td><div class="inv-actions"><button class="inv-edit" onclick="openProductEditor(${p.id})">Tahrirlash</button><button class="inv-delete" onclick="removeProduct(${p.id})">O‘chirish</button></div></td></tr>`}
function filterInventory(){const q=($('#invSearch')?.value||'').toLowerCase(),cat=$('#invCat')?.value||'';document.querySelectorAll('.inv-row').forEach(r=>r.style.display=(!q||r.dataset.name.includes(q))&&(!cat||r.dataset.cat===cat)?'':'none')}
function createProductAndOpen(){const p={id:Date.now(),cat:D.categories[0]?.id||'food',emoji:'',name:{uz:'Yangi mahsulot',ru:'Новый товар'},description:{uz:'',ru:''},unit:{uz:'dona',ru:'шт'},price:0,cost:0,oldPrice:0,stock:0,receivedQty:0,createdAt:new Date().toISOString(),lastReceivedAt:'',image:'',badge:'YANGI',featured:false};D.products.push(p);openProductEditor(p.id,true)}
function closeProductEditor(removeUnsaved=false,id=null){if(removeUnsaved&&id){const p=D.products.find(x=>Number(x.id)===Number(id));if(p&&p.name?.uz==='Yangi mahsulot'&&Number(p.price||0)===0)D.products=D.products.filter(x=>Number(x.id)!==Number(id))}const r=$('#productModalRoot');if(r)r.innerHTML=''}
function openProductEditor(id,isNew=false){const p=D.products.find(x=>Number(x.id)===Number(id));if(!p)return;const r=$('#productModalRoot')||document.body.appendChild(Object.assign(document.createElement('div'),{id:'productModalRoot'}));const units=[['dona','шт'],['kg','кг'],['gram','г'],['metr','м'],['litr','л'],['ml','мл'],['quti','коробка'],['paket','пакет']];r.innerHTML=`<div class="product-modal"><div class="product-modal-card"><div class="product-modal-head"><div><h3>${isNew?'Yangi mahsulot qo‘shish':'Mahsulotni tahrirlash'}</h3><div class="muted small">Oyna faqat “Bekor qilish”, × yoki “Saqlash” orqali yopiladi.</div></div><button class="product-modal-close" onclick="closeProductEditor(${isNew?'true':'false'},${p.id})">×</button></div><div class="product-modal-grid"><div class="product-modal-photo">${p.image?`<img id="editorProductImage" class="inv-img" src="${p.image}" alt="Mahsulot rasmi">`:`<div id="editorProductImageEmpty" class="inv-img-empty">Rasm yo‘q</div>`}<label class="inv-upload">Rasm tanlash<input type="file" accept="image/jpeg,image/png,image/webp" hidden onchange="setProductImage(${p.id},event)"></label>${p.image?`<button class="photo-remove" onclick="removeProductImageEditor(${p.id})" type="button">Rasmni olib tashlash</button>`:''}</div><label>Mahsulot nomi (UZ)<input id="eName" value="${esc(p.name?.uz||'')}"></label><label>Название товара (RU)<input id="eNameRu" value="${esc(p.name?.ru||'')}"></label><label class="wide">Mahsulot ma’lumoti (UZ)<textarea id="eDescUz" placeholder="Mahsulot haqida ma’lumot...">${esc(p.description?.uz||'')}</textarea></label><label class="wide">Описание товара (RU)<textarea id="eDescRu" placeholder="Описание товара для русскоязычного поиска Google...">${esc(p.description?.ru||'')}</textarea></label><label>Kategoriya<select id="eCat">${D.categories.map(c=>`<option value="${c.id}" ${c.id===p.cat?'selected':''}>${esc(c.name?.uz||c.id)}</option>`).join('')}</select></label><label>Birlik / Ед. изм.<select id="eUnit">${units.map(u=>`<option value="${u[0]}" ${(p.unit?.uz||'dona')===u[0]?'selected':''}>${u[0]} / ${u[1]}</option>`).join('')}<option value="other">Boshqa / Другое</option></select></label><label>Birlik (UZ)<input id="eUnitUz" value="${esc(p.unit?.uz||'dona')}"></label><label>Единица (RU)<input id="eUnitRu" value="${esc(p.unit?.ru||'шт')}"></label><label>Sotuv narxi<input id="ePrice" type="number" min="0" value="${p.price||0}"></label><label>Tannarx<input id="eCost" type="number" min="0" value="${p.cost||0}"></label><label>Eski narx<input id="eOld" type="number" min="0" value="${p.oldPrice||0}"></label><label>${isNew?'Qabul qilingan miqdor / Boshlang‘ich zaxira':'Joriy zaxira (Ombordan boshqariladi)'}<input id="eStock" type="number" min="0" step="0.001" value="${p.stock||0}" ${isNew?'':'readonly'}></label><label>Holat<input id="eBadge" value="${esc(p.badge||'Faol')}" placeholder="Faol / YANGI / AKSIYA / TOP"></label></div><div class="product-modal-actions"><button class="btn ghost sm" onclick="closeProductEditor(${isNew?'true':'false'},${p.id})">Bekor qilish</button><button class="btn primary sm" onclick="applyProductEdit(${p.id},${isNew?'true':'false'})">Saqlash</button></div></div></div>`;$('#eUnit').onchange=e=>{const m={dona:['dona','шт'],kg:['kg','кг'],gram:['gram','г'],metr:['metr','м'],litr:['litr','л'],ml:['ml','мл'],quti:['quti','коробка'],paket:['paket','пакет']}[e.target.value];if(m){$('#eUnitUz').value=m[0];$('#eUnitRu').value=m[1]}}}

function applyProductEdit(id,isNew=false){const p=D.products.find(x=>Number(x.id)===Number(id));if(!p)return;p.name=p.name||{};p.name.uz=$('#eName').value.trim()||'Mahsulot';p.name.ru=$('#eNameRu').value.trim()||p.name.uz;p.description=p.description||{};p.description.uz=$('#eDescUz').value.trim();p.description.ru=$('#eDescRu').value.trim()||p.description.uz;p.unit={uz:$('#eUnitUz').value.trim()||'dona',ru:$('#eUnitRu').value.trim()||'шт'};p.cat=$('#eCat').value;p.price=Number($('#ePrice').value);p.cost=Number($('#eCost').value);p.oldPrice=Number($('#eOld').value);p.stock=Number($('#eStock').value);if(isNew){p.receivedQty=p.stock;p.createdAt=p.createdAt||new Date().toISOString()}p.badge=$('#eBadge').value.trim()||'Faol';saveProductsDirect()}
async function saveProductsDirect(){try{await api('/api/admin/catalog',{method:'PUT',body:JSON.stringify({products:D.products,categories:D.categories,settings:D.settings,logo:D.logo})});closeProductEditor();alert('Saqlandi');await refresh()}catch(e){alert(e.message)}}
function productRow(p){return `<div class="product-row" data-id="${p.id}"><div class="product-photo" id="photo-${p.id}">${p.image?`<img src="${p.image}" alt="Mahsulot rasmi">`:`<div class="ph">Rasm yo‘q</div>`}<div class="photo-actions"><label class="photo-btn">Rasm qo‘shish<input type="file" accept="image/jpeg,image/png,image/webp" hidden onchange="setProductImage(${p.id},event)"></label>${p.image?`<button class="photo-remove" onclick="removeProductImage(${p.id})" type="button">×</button>`:''}</div></div><input class="pname" value="${esc(p.name?.uz||'')}" placeholder="Mahsulot nomi"><select class="pcat">${D.categories.map(c=>`<option value="${c.id}" ${c.id===p.cat?'selected':''}>${esc(c.name?.uz||c.id)}</option>`).join('')}</select><input class="pprice" type="number" value="${p.price}" placeholder="Narx"><input class="pcost" type="number" value="${p.cost||0}" placeholder="Tannarx"><input class="pold" type="number" value="${p.oldPrice||0}" placeholder="Eski narx"><input class="pstock" type="number" value="${p.stock}" placeholder="Qoldiq"><input class="pbadge" value="${esc(p.badge||'')}" placeholder="Badge"><button class="btn danger sm" onclick="removeProduct(${p.id})">×</button></div>`}
function addProduct(){D.products.push({id:Date.now(),cat:D.categories[0]?.id||'food',emoji:'',name:{uz:'Yangi mahsulot',ru:'Новый товар'},description:{uz:'',ru:''},unit:{uz:'dona',ru:'шт'},price:0,cost:0,oldPrice:0,stock:0,receivedQty:0,createdAt:new Date().toISOString(),lastReceivedAt:'',image:'',badge:'YANGI',featured:false});renderPane()}
function setProductImage(id,e){const file=e.target.files?.[0];if(!file)return;if(!/^image\/(jpeg|png|webp)$/.test(file.type)){alert('Faqat JPG, PNG yoki WEBP rasm tanlang.');e.target.value='';return}if(file.size>8*1024*1024){alert('Rasm 8 MB dan katta bo‘lmasin.');e.target.value='';return}const img=new Image(),reader=new FileReader();reader.onload=()=>{img.onload=()=>{const max=1200,scale=Math.min(1,max/Math.max(img.width,img.height)),w=Math.max(1,Math.round(img.width*scale)),h=Math.max(1,Math.round(img.height*scale)),c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(img,0,0,w,h);let data='';try{data=c.toDataURL('image/webp',.82)}catch{data=c.toDataURL('image/jpeg',.84)}const p=D.products.find(x=>Number(x.id)===Number(id));if(p){p.image=data;const old=$('#editorProductImage'),empty=$('#editorProductImageEmpty');if(old)old.src=data;else if(empty){const im=document.createElement('img');im.id='editorProductImage';im.className='inv-img';im.src=data;empty.replaceWith(im)}}};img.onerror=()=>alert('Rasmni o‘qib bo‘lmadi.');img.src=reader.result};reader.readAsDataURL(file)}
function removeProductImageEditor(id){const p=D.products.find(x=>Number(x.id)===Number(id));if(p){p.image='';const im=$('#editorProductImage');if(im){const d=document.createElement('div');d.id='editorProductImageEmpty';d.className='inv-img-empty';d.textContent='Rasm yo‘q';im.replaceWith(d)}}}
function removeProductImage(id){const p=D.products.find(x=>Number(x.id)===Number(id));if(p){p.image='';renderPane()}}
function removeProduct(id){if(!confirm('Mahsulot o‘chirilsinmi?'))return;D.products=D.products.filter(x=>Number(x.id)!==Number(id));saveProductsDirect()}
async function saveProducts(){document.querySelectorAll('.product-row').forEach(r=>{const p=D.products.find(x=>Number(x.id)===Number(r.dataset.id));if(!p)return;p.name.uz=r.querySelector('.pname').value;p.name.ru=p.name.ru||p.name.uz;p.cat=r.querySelector('.pcat').value;p.price=Number(r.querySelector('.pprice').value);p.cost=Number(r.querySelector('.pcost').value);p.oldPrice=Number(r.querySelector('.pold').value);p.stock=Number(r.querySelector('.pstock').value);p.badge=r.querySelector('.pbadge').value});try{await api('/api/admin/catalog',{method:'PUT',body:JSON.stringify({products:D.products,categories:D.categories,settings:D.settings,logo:D.logo})});alert('Saqlandi');await refresh()}catch(e){alert(e.message)}}
function customersPane(){return `<div class="panel"><div class="table"><table><thead><tr><th>Mijoz</th><th>Telefon</th><th>Buyurtmalar</th><th>Yakunlangan xarid</th><th>Oxirgi buyurtma</th><th>Asosiy hudud</th></tr></thead><tbody>${D.customers.map(c=>`<tr><td><b>${esc(c.name)}</b></td><td><a href="tel:${esc(c.phone)}">${esc(c.phone)}</a></td><td>${c.orders}</td><td><b>${money(c.total)}</b></td><td>${c.lastOrder?new Date(c.lastOrder).toLocaleString('uz-UZ'):''}</td><td>${esc(Object.entries(c.areas||{}).sort((a,b)=>b[1]-a[1])[0]?.[0]||'')}</td></tr>`).join('')}</tbody></table></div></div>`}
function warehousePane(){const month=new Date().toISOString().slice(0,7),totalStock=(D.products||[]).reduce((a,p)=>a+Number(p.stock||0),0),value=(D.products||[]).reduce((a,p)=>a+Number(p.stock||0)*Number(p.cost||0),0);return `<div class="panel"><div class="inv-head"><div class="inv-title"><h2>Ombor</h2><p>Mahsulot qoldig‘i, qo‘shimcha kirim va premium prays/PDF alohida nazorat qilinadi.</p></div><div class="inv-tools"><input id="warehouseMonth" type="month" value="${month}"><select id="pricePerPage" title="Har sahifaga mahsulotlar soni"><option value="2">2 ta / varoq</option><option value="3">3 ta / varoq</option><option value="4" selected>4 ta / varoq</option></select><button class="btn ghost" onclick="previewPricePdf()">PRO prays preview</button><button class="btn primary js-price-download" onclick="downloadPricePdf(this)">PRO PDF yuklab olish</button><button class="btn primary" onclick="warehouseReport()">Ombor hisobotini Excel yuklash</button></div></div><div class="warehouse-summary"><div class="stat"><span>Mahsulot turlari</span><b>${D.products.length}</b></div><div class="stat"><span>Jami joriy qoldiq</span><b>${totalStock}</b></div><div class="stat"><span>Ombor tannarx qiymati</span><b>${money(value)}</b></div><div class="stat"><span>Kam qoldiq (≤5)</span><b>${D.products.filter(p=>Number(p.stock||0)<=5).length}</b></div></div><div class="inv-table-wrap"><table class="inv-table"><thead><tr><th>#</th><th>Mahsulot</th><th>Название RU</th><th>Birlik</th><th>Tannarx</th><th>Sotuv narxi</th><th>Joriy qoldiq</th><th>Kirim miqdori</th><th>Oxirgi qabul sanasi</th></tr></thead><tbody>${D.products.map((p,i)=>`<tr><td>${i+1}</td><td><b>${esc(p.name?.uz||'')}</b></td><td>${esc(p.name?.ru||'')}</td><td>${esc(p.unit?.uz||'dona')} / ${esc(p.unit?.ru||'шт')}</td><td>${money(p.cost||0)}</td><td>${money(p.price||0)}</td><td><b>${Number(p.stock||0)}</b></td><td><div class="stock-receive"><input id="receive-${p.id}" type="number" min="0.001" step="0.001" placeholder="0" onkeydown="if(event.key==='Enter')receiveStock(${p.id})"><button class="btn primary sm" onclick="receiveStock(${p.id})">+ Qabul qilish</button></div></td><td>${(p.lastReceivedAt||p.createdAt)?new Date(p.lastReceivedAt||p.createdAt).toLocaleDateString('uz-UZ'):'—'}</td></tr>`).join('')}</tbody></table></div><div class="notice" style="margin-top:14px"><b>Kirim:</b> kerakli mahsulot qatorida miqdorni kiriting va “+ Qabul qilish”ni bosing. Joriy qoldiq darhol oshadi va shu oy Excel hisobotidagi “Qabul qilingan” ustuniga qo‘shiladi.<br><b>Hisobot:</b> “Oy oxiriga qoldiq” avtomatik hisoblanadi: Oy boshiga qoldiq + Qabul qilingan − Sotilgan. Bekor qilingan buyurtmalar hisobga olinmaydi.<br><b>PRO prays PDF:</b> mahsulotlar bitta praysda kategoriya bo‘yicha joylashadi. Mahsulot rasmi, nomi, sotuv narxi va ombordagi mavjud qoldiq avtomatik ko‘rinadi. Yangi qo‘shilgan mahsulotlar ham praysga avtomatik qo‘shiladi.</div></div>`}
async function receiveStock(productId){const el=document.getElementById(`receive-${productId}`),qty=Number(el?.value);if(!Number.isFinite(qty)||qty<=0){alert('Qabul miqdorini kiriting.');el?.focus();return}const product=D.products.find(p=>Number(p.id)===Number(productId));if(!confirm(`${product?.name?.uz||'Mahsulot'}: omborga ${qty} qo‘shilsinmi?`))return;try{if(el)el.disabled=true;await api('/api/admin/inventory-receive',{method:'POST',body:JSON.stringify({productId,qty})});await refresh()}catch(e){alert(e.message);if(el)el.disabled=false}}
function warehouseReport(){const m=$('#warehouseMonth').value||new Date().toISOString().slice(0,7);window.location='/api/admin/inventory-report.xls?month='+encodeURIComponent(m)}
function pricePdfImage(src=''){try{return src&&String(src).startsWith('data:')?String(src):new URL(String(src||''),window.location.href).href}catch{return String(src||'')}}
function pricePerPageValue(){return Math.max(2,Math.min(4,Number($('#pricePerPage')?.value||$('#reportPricePerPage')?.value)||4))}
function priceGroups(){const products=(D.products||[]).filter(p=>Number(p.stock||0)>0).slice().sort((a,b)=>String(a.name?.uz||'').localeCompare(String(b.name?.uz||''),'uz'));const groups=[];const used=new Set();(D.categories||[]).forEach(c=>{const items=products.filter(p=>String(p.cat||'')===String(c.id||''));if(items.length){groups.push({id:c.id,name:c.name?.uz||'Kategoriya',nameRu:c.name?.ru||'',emoji:c.emoji||c.icon||'📦',items});used.add(String(c.id||''))}});const other=products.filter(p=>!used.has(String(p.cat||'')));if(other.length)groups.push({id:'other',name:'Boshqa mahsulotlar',nameRu:'Прочие товары',emoji:'📦',items:other});if(!groups.length&&products.length)groups.push({id:'all',name:'Mahsulotlar praysi',nameRu:'Прайс товаров',emoji:'📦',items:products});return groups}
function priceCardHtml(p){return `<article class="pro-price-card"><div class="pro-price-image-wrap">${p.image?`<img class="pro-price-image" src="${pricePdfImage(p.image)}" alt="${esc(p.name?.uz||'Mahsulot')}">`:`<div class="pro-price-noimg"><span>IMOM OTA BARAKA</span><small>Premium mahsulot</small></div>`}</div><div class="pro-price-body"><div class="pro-price-name">${esc(p.name?.uz||'Mahsulot')}</div><div class="pro-price-name-ru">${esc(p.name?.ru||'')}</div><div class="pro-price-meta"><span class="pro-chip unit">${esc(p.unit?.uz||'dona')}</span><span class="pro-chip stock">Omborda: ${Number(p.stock||0)}</span></div><div class="pro-price-bottom"><div><div class="pro-price-label">Sotuv narxi</div><div class="pro-price-value">${money(p.price||0)}</div></div><div class="pro-sku-tag">${esc(p.badge||'MAVJUD')}</div></div></div></article>`}
function buildPricePages(){const perPage=pricePerPageValue(),groups=priceGroups(),pages=[];groups.forEach(group=>{for(let i=0;i<group.items.length;i+=perPage){pages.push({group,items:group.items.slice(i,i+perPage),part:Math.floor(i/perPage)+1,parts:Math.ceil(group.items.length/perPage)})}});return pages}
function priceDocumentStyles(){return `<style>@page{size:A4 landscape;margin:10mm}*{box-sizing:border-box}body{margin:0;padding:0;font-family:Arial,sans-serif;background:#edf3ef;color:#12372d;-webkit-print-color-adjust:exact;print-color-adjust:exact}.pro-price-doc{padding:0}.pro-price-page{width:277mm;min-height:190mm;background:linear-gradient(180deg,#fefefe 0%,#f3f7f4 100%);position:relative;overflow:hidden;border:1px solid #d8e4dd;border-radius:18px;padding:10mm;page-break-after:always}.pro-price-page:last-child{page-break-after:auto}.pro-price-page:before,.pro-price-page:after{content:'';position:absolute;border-radius:50%;pointer-events:none}.pro-price-page:before{width:165mm;height:165mm;right:-55mm;top:-75mm;background:radial-gradient(circle,rgba(7,88,76,.13),rgba(7,88,76,0))}.pro-price-page:after{width:125mm;height:125mm;left:-40mm;bottom:-55mm;background:radial-gradient(circle,rgba(214,174,59,.11),rgba(214,174,59,0))}.pro-head{display:flex;justify-content:space-between;align-items:flex-start;gap:10mm;position:relative;z-index:1}.pro-brand{display:flex;gap:5mm;align-items:center}.pro-logo{width:24mm;height:24mm;border-radius:50%;padding:2mm;background:radial-gradient(circle at 30% 20%,#fff,#dcefe6 65%,#95bfaf);border:1px solid #d8e6df;object-fit:contain}.pro-eyebrow{font-size:10px;letter-spacing:3px;color:#0a6852;font-weight:800;text-transform:uppercase}.pro-title{font:800 24px Georgia,serif;color:#07584c;line-height:1.06;margin:1mm 0 1mm}.pro-sub{font-size:11px;color:#5f746c;max-width:120mm}.pro-datebox{padding:4mm 5mm;border-radius:14px;background:linear-gradient(135deg,#0b6c57,#0d4c40);color:#fff;min-width:56mm;box-shadow:0 12px 24px rgba(7,88,76,.14)}.pro-datebox .small{font-size:10px;opacity:.82}.pro-datebox b{display:block;margin-top:1.5mm;font-size:13px}.pro-catbar{margin-top:5mm;background:linear-gradient(135deg,#0d704f,#0a5948 68%,#e1b641 150%);color:#fff;border-radius:16px;padding:5mm 6mm;display:flex;justify-content:space-between;align-items:center;gap:6mm;position:relative;z-index:1;box-shadow:0 12px 24px rgba(7,88,76,.10)}.pro-cat-left{display:flex;align-items:center;gap:4mm}.pro-cat-icon{width:14mm;height:14mm;border-radius:50%;display:flex;align-items:center;justify-content:center;background:rgba(255,255,255,.16);font-size:22px}.pro-cat-title{font:800 17px Georgia,serif;line-height:1.1}.pro-cat-ru{font-size:11px;opacity:.84;margin-top:1mm}.pro-cat-right{display:flex;gap:3mm;flex-wrap:wrap;justify-content:flex-end}.pro-mini-chip{background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.18);padding:2.3mm 3.5mm;border-radius:999px;font-size:10px;font-weight:700}.pro-price-grid{margin-top:6mm;display:grid;grid-template-columns:repeat(2,1fr);gap:5mm;position:relative;z-index:1}.pro-price-card{background:rgba(255,255,255,.96);border:1px solid #dde8e2;border-radius:16px;overflow:hidden;box-shadow:0 8px 22px rgba(15,74,55,.08);display:flex;min-height:56mm}.pro-price-image-wrap{width:40%;background:linear-gradient(180deg,#f8fbf9,#ecf3ef);display:flex;align-items:center;justify-content:center;padding:4mm}.pro-price-image{max-width:100%;max-height:100%;object-fit:contain;mix-blend-mode:multiply}.pro-price-noimg{width:100%;height:100%;border:1px dashed #bfd7cd;border-radius:12px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;color:#7b9088;padding:4mm}.pro-price-noimg span{font-weight:800;font-size:12px}.pro-price-noimg small{margin-top:1mm;font-size:10px}.pro-price-body{flex:1;padding:4.2mm;display:flex;flex-direction:column}.pro-price-name{font-size:14px;font-weight:800;color:#12372d;line-height:1.18;min-height:11mm}.pro-price-name-ru{font-size:10px;color:#6d8178;min-height:5mm;margin-top:1mm}.pro-price-meta{display:flex;gap:2.5mm;flex-wrap:wrap;margin-top:2.2mm}.pro-chip{display:inline-flex;align-items:center;border-radius:999px;padding:2mm 3.2mm;font-size:10px;font-weight:700}.pro-chip.unit{background:#edf6f2;color:#0d6a54}.pro-chip.stock{background:#fff2d8;color:#946300}.pro-price-bottom{margin-top:auto;display:flex;justify-content:space-between;align-items:flex-end;gap:4mm;border-top:1px solid #e6efea;padding-top:3mm}.pro-price-label{font-size:9px;text-transform:uppercase;color:#70837b;letter-spacing:.8px}.pro-price-value{margin-top:1mm;font-size:18px;font-weight:900;color:#07584c;line-height:1}.pro-sku-tag{padding:2.2mm 3.5mm;border-radius:999px;background:linear-gradient(135deg,#f0f5f2,#e4efe9);color:#47675c;font-size:9px;font-weight:800;text-transform:uppercase}.pro-footer{margin-top:5mm;border-top:1px solid #dce9e2;padding-top:3mm;display:flex;justify-content:space-between;align-items:center;gap:5mm;color:#587067;font-size:10px;position:relative;z-index:1}.pro-footer b{color:#12372d}.pro-page-no{font-weight:800;color:#07584c}.pro-actions{position:sticky;top:0;z-index:3;display:flex;justify-content:flex-end;gap:8px;padding:12px;background:#edf3ef;border-bottom:1px solid #d9e7e0}.pro-actions button{border:0;border-radius:12px;padding:10px 14px;cursor:pointer;font-weight:800}.pro-actions .ghost{background:#fff;color:#275347;border:1px solid #cfe0d8}.pro-actions .primary{background:#07584c;color:#fff}.pro-hero-note{display:flex;gap:3mm;align-items:center;margin-top:4mm;color:#4f665e;font-size:11px;position:relative;z-index:1}.pro-hero-note span{display:inline-flex;width:9mm;height:9mm;border-radius:50%;align-items:center;justify-content:center;background:#e9f4ef;color:#0d6a54;font-weight:900}@media print{body{background:#fff}.pro-actions{display:none}.pro-price-page{border:none;border-radius:0;box-shadow:none}}</style>`}
function buildPriceMarkup(){const pages=buildPricePages(),logo=pricePdfImage(D.logo||'logo.png'),siteName=esc(D.settings?.siteName||'IMOM OTA BARAKA'),domain=esc(D.settings?.siteDomain||window.location.host||''),phone=esc(D.settings?.phone||''),today=esc(new Date().toLocaleDateString('uz-UZ'));return {pages,markup:`<div class="pro-price-doc">${pages.map((page,idx)=>`<section class="pro-price-page">${idx===0?`<div class="pro-head"><div class="pro-brand"><img class="pro-logo" src="${logo}" alt="Logo"><div><div class="pro-eyebrow">Premium Price List</div><div class="pro-title">${siteName}</div></div></div><div class="pro-datebox"><div class="small">Yangilangan sana</div><b>${today}</b></div></div>`:''}<div class="pro-price-grid" style="${idx===0?'margin-top:7mm':'margin-top:0'}">${page.items.map(priceCardHtml).join('')}</div><div class="pro-footer"><div><b>${siteName}</b>${domain?` • ${domain}`:''}${phone?` • ${phone}`:''}</div><div class="pro-page-no">${idx+1} / ${pages.length}</div></div></section>`).join('')}</div>`}}
function loadRemoteScript(src){return new Promise((resolve,reject)=>{if([...document.scripts].some(s=>s.src===src))return resolve();const s=document.createElement('script');s.src=src;s.async=true;s.onload=resolve;s.onerror=()=>reject(new Error('Skript yuklanmadi: '+src));document.head.appendChild(s)})}
async function ensurePricePdfLibs(){if(window.jspdf&&window.html2canvas)return;if(!window.__pricePdfLibPromise){window.__pricePdfLibPromise=(async()=>{if(!window.html2canvas)await loadRemoteScript('https://cdn.jsdelivr.net/npm/html2canvas@1.4.1/dist/html2canvas.min.js');if(!window.jspdf)await loadRemoteScript('https://cdn.jsdelivr.net/npm/jspdf@2.5.1/dist/jspdf.umd.min.js')})().catch(err=>{window.__pricePdfLibPromise=null;throw err})}return window.__pricePdfLibPromise}
async function downloadPricePdf(btn){try{if(btn){btn.disabled=true;btn.dataset.prevText=btn.textContent;btn.textContent='PDF tayyorlanmoqda...'}await ensurePricePdfLibs();const {markup,pages}=buildPriceMarkup();if(!pages.length)throw new Error('Prays uchun mahsulotlar topilmadi.');const root=document.createElement('div');root.style.position='fixed';root.style.left='-20000px';root.style.top='0';root.style.width='297mm';root.style.zIndex='-1';root.innerHTML=priceDocumentStyles()+markup;document.body.appendChild(root);const pageEls=[...root.querySelectorAll('.pro-price-page')];const {jsPDF}=window.jspdf;const pdf=new jsPDF({orientation:'landscape',unit:'mm',format:'a4',compress:true});for(let i=0;i<pageEls.length;i++){const canvas=await window.html2canvas(pageEls[i],{scale:2,useCORS:true,backgroundColor:'#eef4f0'});const img=canvas.toDataURL('image/jpeg',0.94);if(i>0)pdf.addPage('a4','landscape');pdf.addImage(img,'JPEG',0,0,297,210,undefined,'FAST')}const stamp=($('#warehouseMonth')?.value||new Date().toISOString().slice(0,7)).replace(/[^0-9-]/g,'');pdf.save(`IMOM_OTA_BARAKA_PRO_PRAYS_${stamp}.pdf`);root.remove()}catch(e){alert((e&&e.message?e.message:e)+'\n\nAgar to‘g‘ridan-to‘g‘ri PDF yuklash ishlamasa, “PRO prays preview” tugmasidan kirib Save as PDF qiling.');console.error(e)}finally{if(btn){btn.disabled=false;btn.textContent=btn.dataset.prevText||'PRO PDF yuklab olish'}}}

function reportsPane(){const today=new Date().toISOString().slice(0,10),month=today.slice(0,7),year=today.slice(0,4);return `<div class="report-grid"><div class="report-card"><h3>Kunlik hisobot</h3><input id="rday" type="date" value="${today}"><button class="btn primary sm" onclick="report('daily',$('#rday').value)">Excel yuklash</button></div><div class="report-card"><h3>Oylik hisobot</h3><input id="rmonth" type="month" value="${month}"><button class="btn primary sm" onclick="report('monthly',$('#rmonth').value)">Excel yuklash</button></div><div class="report-card"><h3>Yillik hisobot</h3><input id="ryear" type="number" value="${year}" min="2020" max="2100"><button class="btn primary sm" onclick="report('yearly',$('#ryear').value)">Excel yuklash</button></div><div class="report-card"><h3>Sana oralig‘i</h3><input id="rfrom" type="date"><input id="rto" type="date"><select id="rstatus"><option value="">Barcha statuslar</option><option value="done">Yakunlangan</option><option value="cancelled">Bekor qilingan</option></select><button class="btn primary sm" onclick="customReport()">Excel yuklash</button></div><div class="report-card"><h3>PRO prays PDF</h3><select id="reportPricePerPage"><option value="2">2 ta / varoq</option><option value="3">3 ta / varoq</option><option value="4" selected>4 ta / varoq</option></select><div style="display:grid;gap:8px"><button class="btn ghost sm" onclick="previewPricePdf()">Preview ochish</button><button class="btn primary sm js-price-download" onclick="downloadPricePdf(this)">PDF yuklab olish</button></div></div></div><div class="panel"><h3>Hisobot tarkibi</h3><p class="muted">Buyurtma, sana, mijoz, telefon, Parkent hududi, manzil, yetkazish vaqti, mahsulotlar, chegirma, tushum, tannarx, foyda va status. Alohida “PRO prays PDF” bo‘limida kategoriya bo‘yicha premium katalog ko‘rinishidagi PDF to‘g‘ridan-to‘g‘ri yuklab olinadi.</p></div>`}
function report(period,value){window.location=`/api/admin/reports.xls?period=${encodeURIComponent(period)}&value=${encodeURIComponent(value)}`}
function customReport(){window.location=`/api/admin/reports.xls?period=custom&from=${encodeURIComponent($('#rfrom').value)}&to=${encodeURIComponent($('#rto').value)}&status=${encodeURIComponent($('#rstatus').value)}`}

let FIN=null, financeSection='dashboard';
function financePane(){const now=new Date(),day=now.toISOString().slice(0,10),month=day.slice(0,7),year=day.slice(0,4);return `<div class="finance-shell"><div class="finance-hero"><h2>FINANS ERP — Moliyaviy boshqaruv</h2><p>Prixod, avtomatik rashod, sotuv, firmalar, akt sverka, ish haqi, soliq majburiyatlari, xarajatlar, balans va Excel hisobotlar bitta tizimda.</p><div class="finance-filters"><label>Davr<select id="finPeriod" onchange="loadFinance()"><option value="daily">Kunlik</option><option value="monthly" selected>Oylik</option><option value="yearly">Yillik</option></select></label><label>Kun<input id="finDay" type="date" value="${day}" onchange="loadFinance()"></label><label>Oy<input id="finMonth" type="month" value="${month}" onchange="loadFinance()"></label><label>Yil<input id="finYear" type="number" min="2020" max="2100" value="${year}" onchange="loadFinance()"></label><button class="btn primary" onclick="loadFinance()">Yangilash</button></div></div><div class="fin-erp-tabs">${[['dashboard','Dashboard'],['purchases','Xaridlar / Prixod'],['sales','Sotuv / Rashod'],['companies','Firmalar / Akt sverka'],['payroll','Ish haqi'],['taxes','Soliq majburiyatlari'],['expenses','Boshqa xarajatlar'],['reports','Balans / Hisobot']].map(x=>`<button class="fin-erp-tab ${financeSection===x[0]?'active':''}" onclick="setFinanceSection('${x[0]}')">${x[1]}</button>`).join('')}</div><div id="financeRoot"><div class="panel">Finans ma’lumotlari yuklanmoqda...</div></div></div>`}
function setFinanceSection(sec){financeSection=sec;document.querySelectorAll('.fin-erp-tab').forEach(b=>b.classList.toggle('active',b.getAttribute('onclick')?.includes(`'${sec}'`)));renderFinance()}
function finQuery(){const p=$('#finPeriod')?.value||'monthly';let value=p==='daily'?$('#finDay')?.value:p==='yearly'?$('#finYear')?.value:$('#finMonth')?.value;return {period:p,value:value||'',year:$('#finYear')?.value||new Date().getFullYear()}}
async function loadFinance(){try{const q=finQuery();FIN=await api(`/api/admin/finance?period=${encodeURIComponent(q.period)}&value=${encodeURIComponent(q.value)}&year=${encodeURIComponent(q.year)}`);renderFinance()}catch(e){const r=$('#financeRoot');if(r)r.innerHTML=`<div class="panel danger">${esc(e.message)}</div>`}}
function finMoney(v){return money(Math.round(Number(v)||0))}
function finChart(series){const max=Math.max(1,...(series||[]).flatMap(x=>[Number(x.revenue)||0,Math.max(0,Number(x.netProfit)||0)]));return `<div class="fin-legend"><span><i class="r"></i>Sotuv aylanmasi</span><span><i class="p"></i>Sof natija</span></div><div class="fin-chart">${(series||[]).map((x,i)=>`<div class="fin-chart-col" title="${x.month}: ${finMoney(x.revenue)} / ${finMoney(x.netProfit)}"><div class="fin-bar-rev" style="height:${Math.max(2,(Number(x.revenue)||0)/max*100)}%"></div><div class="fin-bar-profit" style="height:${Math.max(2,Math.max(0,Number(x.netProfit)||0)/max*100)}%"></div><span class="fin-chart-label">${String(i+1).padStart(2,'0')}</span></div>`).join('')}</div>`}
function finCompany(id){return (FIN?.companies||[]).find(x=>String(x.id)===String(id))}
function finProduct(id){return (FIN?.products||D.products||[]).find(x=>Number(x.id)===Number(id))}
function renderFinance(){if(!FIN)return;const root=$('#financeRoot');if(!root)return;const renderers={dashboard:renderFinanceDashboard,purchases:renderFinancePurchases,sales:renderFinanceSales,companies:renderFinanceCompanies,payroll:renderFinancePayroll,taxes:renderFinanceTaxes,expenses:renderFinanceExpenses,reports:renderFinanceReports};root.innerHTML=(renderers[financeSection]||renderFinanceDashboard)()}
function renderFinanceDashboard(){const s=FIN.summary||{},b=FIN.balance||{},year=$('#finYear')?.value||new Date().getFullYear();return `<div class="fin-pane"><div class="fin-kpis"><div class="fin-kpi good"><span>Sotuv aylanmasi</span><b>${finMoney(s.revenue)}</b></div><div class="fin-kpi good"><span>Yalpi foyda</span><b>${finMoney(s.grossProfit)}</b></div><div class="fin-kpi ${Number(s.netProfit)>=0?'good':'bad'}"><span>Sof natija</span><b>${finMoney(s.netProfit)}</b></div><div class="fin-kpi warn"><span>Hisoblangan soliqlar</span><b>${finMoney(s.taxAccrued)}</b></div><div class="fin-kpi"><span>Prixod / Xarid</span><b>${finMoney(s.purchaseTotal)}</b></div><div class="fin-kpi"><span>Ish haqi fondi</span><b>${finMoney(s.payrollGross)}</b></div><div class="fin-kpi warn"><span>Firmalarga qarz</span><b>${finMoney(b.supplierDebt)}</b></div><div class="fin-kpi warn"><span>Soliq qarzi</span><b>${finMoney(b.taxDebt)}</b></div></div><div class="fin-grid2"><div class="fin-card"><div class="fin-section-title"><h3>PRO moliyaviy diagramma — ${esc(year)}</h3><span class="role-badge">12 oy</span></div>${finChart(FIN.series||[])}</div><div class="fin-card"><h3>Avtomatik balans</h3><div class="fin-balance"><div><span>Kassa</span><b>${finMoney(b.cash)}</b></div><div><span>Bank</span><b>${finMoney(b.bank)}</b></div><div><span>Ombor qiymati</span><b>${finMoney(b.inventoryValue)}</b></div><div><span>Aktivlar</span><b>${finMoney(b.assets)}</b></div><div><span>Majburiyatlar</span><b>${finMoney(b.liabilities)}</b></div><div><span>Kapital / Netto</span><b>${finMoney(b.equity)}</b></div></div><div class="fin-auto-note" style="margin-top:12px">Sotuv “Yakunlandi” bo‘lganda tushum Finansga avtomatik kiradi. “Yetkazilmoqda” yoki “Yakunlandi” statusida mahsulot ombordan avtomatik rashod qilinadi.</div></div></div></div>`}
function renderFinancePurchases(){const companies=FIN.companies||[],products=FIN.products||[],purchases=FIN.purchases||[],st=FIN.settings||{},today=new Date().toISOString().slice(0,10);return `<div class="fin-pane"><div class="fin-grid2"><div class="fin-card"><div class="fin-toolbar"><h3>Tashkilotdan mahsulot prixod qilish</h3><span class="role-badge">Omborga avtomatik kirim</span></div><div class="fin-form"><label>Yetkazib beruvchi firma<select id="purCompany">${companies.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><label>Mahsulot<select id="purProduct" onchange="calcPurchasePricing()">${products.map(p=>`<option value="${p.id}">${esc(p.name)} • qoldiq ${p.stock}</option>`).join('')}</select></label><label>Miqdor<input id="purQty" type="number" min="0.001" step="0.001" oninput="calcPurchasePricing()"></label><label>Xarid narxi / 1 birlik<input id="purUnitCost" type="number" min="0" oninput="calcPurchasePricing()"></label><label>Transport<input id="purTransport" type="number" value="0" oninput="calcPurchasePricing()"></label><label>Boshqa xarajat<input id="purExtra" type="number" value="0" oninput="calcPurchasePricing()"></label><label>Ustama %<input id="purMarkup" type="number" step="0.01" value="${Number(st.defaultMarkupRate||30)}" oninput="calcPurchasePricing()"></label><label>Sotuv narxi<input id="purSalePrice" type="number" min="0" placeholder="Avtomatik hisoblanadi"></label><label>Boshlang‘ich to‘lov<input id="purPaid" type="number" value="0"></label><label>To‘lov hisobi<select id="purAccount"><option value="bank">Bank</option><option value="cash">Kassa</option></select></label><label>Sana<input id="purDate" type="date" value="${today}"></label><label>Nakladnoy / hujjat №<input id="purInvoice"></label><label class="wide">Izoh<input id="purNote" placeholder="Ixtiyoriy izoh"></label><button class="btn primary wide" onclick="addFinancePurchase()">+ Prixodni saqlash</button></div><div id="purCalc" class="fin-price-preview" style="margin-top:12px"><div><span>Jami xarid</span><b>0 so‘m</b></div><div><span>1 birlik tannarx</span><b>0 so‘m</b></div><div><span>Tavsiya sotuv</span><b>0 so‘m</b></div><div><span>Yangi qoldiq</span><b>0</b></div></div><div class="fin-auto-note" style="margin-top:12px">Prixod saqlanganda ombor qoldig‘i oshadi, o‘rtacha tannarx qayta hisoblanadi, firma qarzdorligi shakllanadi va shu yerda kiritilgan sotuv narxi mahsulot kartasiga avtomatik o‘rnatiladi.</div></div><div class="fin-card"><h3>So‘nggi prixodlar</h3><div class="fin-table"><table><thead><tr><th>Sana</th><th>Firma</th><th>Mahsulot</th><th>Miqdor</th><th>Xarid narxi</th><th>Sotuv narxi</th><th>Jami</th><th>Hujjat</th></tr></thead><tbody>${purchases.slice(0,100).map(x=>{const c=finCompany(x.companyId),p=finProduct(x.productId);return `<tr><td>${esc(x.date||'')}</td><td>${esc(c?.name||'')}</td><td><b>${esc(p?.name||'')}</b></td><td>${x.qty} ${esc(p?.unit||'')}</td><td>${finMoney(x.unitCost)}</td><td>${finMoney(x.salePrice||x.suggestedSalePrice)}</td><td>${finMoney(x.total)}</td><td>${esc(x.invoice||'—')}</td></tr>`}).join('')||'<tr><td colspan="8" class="fin-empty">Prixod yo‘q</td></tr>'}</tbody></table></div></div></div></div>`}
function calcPurchasePricing(){const qty=Number($('#purQty')?.value)||0,cost=Number($('#purUnitCost')?.value)||0,tr=Number($('#purTransport')?.value)||0,ex=Number($('#purExtra')?.value)||0,markup=Number($('#purMarkup')?.value)||0,p=finProduct($('#purProduct')?.value),total=qty*cost+tr+ex,landed=qty>0?total/qty:0,suggested=Math.round(landed*(1+markup/100)),newStock=Number(p?.stock||0)+qty;if($('#purSalePrice')&&!Number($('#purSalePrice').value))$('#purSalePrice').value=suggested||'';const r=$('#purCalc');if(r)r.innerHTML=`<div><span>Jami xarid</span><b>${finMoney(total)}</b></div><div><span>1 birlik tannarx</span><b>${finMoney(landed)}</b></div><div><span>Tavsiya sotuv</span><b>${finMoney(suggested)}</b></div><div><span>Yangi qoldiq</span><b>${newStock}</b></div>`}
function renderFinanceSales(){const sales=FIN.sales||[];const rows=[];for(const o of sales)for(const it of o.items||[])rows.push({order:o.orderId,date:o.date,status:o.status,customer:o.customer,...it});const totalQty=rows.reduce((a,x)=>a+Number(x.qty||0),0),rev=rows.reduce((a,x)=>a+Number(x.amount||0),0),cogs=rows.reduce((a,x)=>a+Number(x.costAmount||0),0);return `<div class="fin-pane"><div class="fin-total-box"><div><span>Avtomatik rashod miqdori</span><b>${totalQty}</b></div><div><span>Sotuv summasi</span><b>${finMoney(rev)}</b></div><div><span>Tannarx summasi</span><b>${finMoney(cogs)}</b></div><div><span>Taxminiy yalpi foyda</span><b>${finMoney(rev-cogs)}</b></div></div><div class="fin-card"><div class="fin-toolbar"><h3>Sotuv / Rashod jurnali</h3><span class="role-badge">Buyurtmalardan avtomatik</span></div><div class="fin-auto-note">Bu bo‘limga ma’lumot qo‘lda kiritilmaydi. Buyurtma “Yetkazilmoqda” yoki “Yakunlandi” holatiga o‘tganda ombor rashodi avtomatik yoziladi. Moliyaviy tushum esa “Yakunlandi” statusida hisoblanadi.</div><div class="fin-table" style="margin-top:12px"><table><thead><tr><th>Sana</th><th>Buyurtma</th><th>Mijoz</th><th>Mahsulot</th><th>Miqdor</th><th>Sotuv narxi</th><th>Summa</th><th>Status</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.date||'')}</td><td>${esc(x.order)}</td><td>${esc(x.customer||'')}</td><td><b>${esc(x.name||'')}</b></td><td>${x.qty} ${esc(x.unit||'')}</td><td>${finMoney(x.salePrice)}</td><td>${finMoney(x.amount)}</td><td><span class="fin-sales-status ${x.status}">${x.status==='done'?'Yakunlandi':'Yetkazilmoqda'}</span></td></tr>`).join('')||'<tr><td colspan="8" class="fin-empty">Tanlangan davrda sotuv/rashod yo‘q</td></tr>'}</tbody></table></div></div></div>`}
function renderFinanceCompanies(){const companies=FIN.companies||[],today=new Date().toISOString().slice(0,10),year=today.slice(0,4);return `<div class="fin-pane"><div class="fin-grid2"><div class="fin-card"><h3>Firmalar / Yetkazib beruvchilar</h3><div class="fin-form"><label>Firma nomi<input id="coName"></label><label>STIR / INN<input id="coInn"></label><label>Telefon<input id="coPhone"></label><label>Izoh<input id="coNote"></label><button class="btn primary wide" onclick="addFinanceCompany()">+ Firma qo‘shish</button></div><div class="fin-table" style="margin-top:12px"><table><thead><tr><th>Firma</th><th>Olingan</th><th>To‘langan</th><th>Qarz</th></tr></thead><tbody>${companies.map(c=>`<tr><td><b>${esc(c.name)}</b><br><span class="muted">${esc(c.inn||'')}</span></td><td>${finMoney(c.purchases)}</td><td>${finMoney(c.paid)}</td><td><b>${finMoney(c.debt)}</b></td></tr>`).join('')||'<tr><td colspan="4" class="fin-empty">Firma yo‘q</td></tr>'}</tbody></table></div></div><div class="fin-card"><h3>Firmaga to‘lov</h3><div class="fin-form"><label>Firma<select id="payCompany">${companies.map(c=>`<option value="${c.id}">${esc(c.name)} — qarz ${finMoney(c.debt)}</option>`).join('')}</select></label><label>Summa<input id="payCompanyAmount" type="number"></label><label>Sana<input id="payCompanyDate" type="date" value="${today}"></label><label>Hisob<select id="payCompanyAccount"><option value="bank">Bank</option><option value="cash">Kassa</option></select></label><label class="wide">Izoh<input id="payCompanyNote"></label><button class="btn primary wide" onclick="addCompanyPayment()">To‘lovni saqlash</button></div><hr style="border:0;border-top:1px solid #e4ece8;margin:18px 0"><h3>Akt sverka</h3><div class="fin-form"><label>Firma<select id="reconCompany">${companies.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><label>Boshlanish<input id="reconFrom" type="date" value="${year}-01-01"></label><label>Tugash<input id="reconTo" type="date" value="${today}"></label><button class="btn primary wide" onclick="downloadReconciliation()">Akt sverka Excel yuklash</button></div><div class="fin-auto-note" style="margin-top:12px">Akt sverka firmadan olingan barcha prixodlarni debet, firmaga qilingan to‘lovlarni kredit qilib ko‘rsatadi va davr oxiridagi qarzni avtomatik chiqaradi.</div></div></div></div>`}
function renderFinancePayroll(){const employees=FIN.employees||[],payroll=FIN.payroll||[],month=$('#finMonth')?.value||new Date().toISOString().slice(0,7),today=new Date().toISOString().slice(0,10);return `<div class="fin-pane"><div class="fin-grid2"><div class="fin-card"><h3>Ishchilar ro‘yxati</h3><div class="fin-form"><label>F.I.Sh.<input id="empName"></label><label>Lavozim<input id="empPosition"></label><label>Oylik<input id="empSalary" type="number"></label><label>Telefon<input id="empPhone"></label><label>Ishga kirgan sana<input id="empStarted" type="date" value="${today}"></label><button class="btn primary wide" onclick="addEmployee()">+ Ishchi qo‘shish</button></div><div class="fin-table" style="margin-top:12px"><table><thead><tr><th>F.I.Sh.</th><th>Lavozim</th><th>Oylik</th><th>Holat</th><th>Amal</th></tr></thead><tbody>${employees.map(e=>`<tr><td><b>${esc(e.name)}</b><br><span class="muted">${esc(e.phone||'')}</span></td><td>${esc(e.position||'')}</td><td>${finMoney(e.salary)}</td><td><span class="${e.active===false?'fin-badge-off':'fin-badge-active'}">${e.active===false?'Ishdan bo‘shagan':'Faol'}</span></td><td><div class="fin-row-actions"><button onclick="editEmployee('${e.id}')">Tahrirlash</button>${e.active===false?`<button onclick="toggleEmployee('${e.id}',true)">Faollashtirish</button>`:`<button class="warn" onclick="toggleEmployee('${e.id}',false)">Ishdan bo‘shatish</button>`}<button class="danger" onclick="deleteEmployee('${e.id}')">O‘chirish</button></div></td></tr>`).join('')||'<tr><td colspan="5" class="fin-empty">Ishchi yo‘q</td></tr>'}</tbody></table></div></div><div class="fin-card"><div class="fin-toolbar"><h3>Oylik shakllantirish</h3><span class="role-badge">Faol ishchilar</span></div><div class="fin-form"><label class="wide">Oy<input id="payrollMonth" type="month" value="${month}"></label><button class="btn primary wide" onclick="generatePayroll()">Oylikni shakllantirish</button></div><div class="fin-table" style="margin-top:12px"><table><thead><tr><th>Oy</th><th>Ishchi</th><th>Gross</th><th>Bonus</th><th>Avans</th><th>Ushlanma</th><th>To‘lanadi</th><th>To‘langan</th><th></th></tr></thead><tbody>${payroll.filter(x=>x.month===month).map(x=>`<tr><td>${esc(x.month)}</td><td><b>${esc(x.name)}</b></td><td>${finMoney(x.gross)}</td><td><input id="pb-${x.id}" type="number" value="${Number(x.bonus||0)}"></td><td><input id="pa-${x.id}" type="number" value="${Number(x.advance||0)}"></td><td><input id="pd-${x.id}" type="number" value="${Number(x.deduction||0)}"></td><td>${finMoney(x.payable)}</td><td><input id="pp-${x.id}" type="number" value="${Number(x.paid||0)}"></td><td><button class="btn ghost sm" onclick="savePayroll('${x.id}')">Saqlash</button></td></tr>`).join('')||'<tr><td colspan="9" class="fin-empty">Bu oy uchun oylik hali shakllanmagan</td></tr>'}</tbody></table></div></div></div></div>`}
function renderFinanceTaxes(){const s=FIN.summary||{},st=FIN.settings||{},today=new Date().toISOString().slice(0,10);const pit=Number(st.payrollIncomeTaxRate??st.payrollTaxRate??12),pension=Number(st.payrollPensionRate??0.1),budget=Number(st.payrollBudgetShareRate??11.9),social=Number(st.employerSocialTaxRate??0);return `<div class="fin-pane"><div class="fin-grid2"><div class="fin-card"><h3>Soliq stavkalari — admin boshqaruvi</h3><div class="fin-form"><label>Sotuvdan aylanma solig‘i %<input id="fsTurn" type="number" step="0.01" value="${Number(st.turnoverTaxRate||4)}"></label><label>Oylik JShDS asosiy stavka %<input id="fsPayrollIncome" type="number" step="0.01" value="${pit}"></label><label>JShDS ichidagi INPS ulushi %<input id="fsPension" type="number" step="0.01" value="${pension}"></label><label>JShDS byudjet ulushi %<input id="fsBudgetShare" type="number" step="0.01" value="${budget}"></label><label>Ish beruvchi ijtimoiy soliq %<input id="fsSocial" type="number" step="0.01" value="${social}"></label><label>Yer solig‘i / oy<input id="fsLand" type="number" value="${Number(st.landTaxMonthly||0)}"></label><label>Mol-mulk solig‘i bazasi<input id="fsPropBase" type="number" value="${Number(st.propertyTaxBase||0)}"></label><label>Mol-mulk yillik %<input id="fsPropRate" type="number" step="0.01" value="${Number(st.propertyTaxRate||0)}"></label><label>Boshqa soliq %<input id="fsOtherRate" type="number" step="0.01" value="${Number(st.otherTaxRate||0)}"></label><label>Boshqa soliq bazasi<select id="fsOtherBase"><option value="revenue" ${st.otherTaxBase==='revenue'?'selected':''}>Sotuv aylanmasi</option><option value="payroll" ${st.otherTaxBase==='payroll'?'selected':''}>Oylik fondi</option><option value="fixed" ${st.otherTaxBase==='fixed'?'selected':''}>Aniq oylik summa</option></select></label><label>Boshqa soliq / oy<input id="fsOtherMonthly" type="number" value="${Number(st.otherTaxMonthly||0)}"></label><label>Standart savdo ustamasi %<input id="fsMarkup" type="number" step="0.01" value="${Number(st.defaultMarkupRate||30)}"></label><label>Sotuv tushumi hisobi<select id="fsSalesAcc"><option value="bank" ${st.defaultSalesAccount!=='cash'?'selected':''}>Bank</option><option value="cash" ${st.defaultSalesAccount==='cash'?'selected':''}>Kassa</option></select></label><label>Boshlang‘ich kassa<input id="fsCash" type="number" value="${Number(st.cashOpening||0)}"></label><label>Boshlang‘ich bank<input id="fsBank" type="number" value="${Number(st.bankOpening||0)}"></label><button class="btn primary wide" onclick="saveFinanceSettings()">Soliq va moliya sozlamalarini saqlash</button></div><div class="fin-auto-note" style="margin-top:12px">0.1% va 11.9% JShDS 12% ning ichki taqsimoti sifatida ko‘rsatiladi; ular 12% ustiga yana qo‘shilmaydi. Stavkalar o‘zgarsa admin bu yerda qo‘lda almashtiradi.</div></div><div class="fin-card"><h3>Tanlangan davr soliq majburiyatlari</h3><div class="fin-tax-split"><div><span>Aylanma solig‘i</span><b>${finMoney(s.turnoverTax)}</b></div><div><span>JShDS ${pit}%</span><b>${finMoney(s.payrollTax)}</b></div><div><span>INPS ulushi ${pension}%</span><b>${finMoney(s.payrollPensionShare)}</b></div><div><span>Byudjet ulushi ${budget}%</span><b>${finMoney(s.payrollBudgetShare)}</b></div><div><span>Ijtimoiy soliq ${social}%</span><b>${finMoney(s.employerSocialTax)}</b></div><div><span>Yer solig‘i</span><b>${finMoney(s.landTax)}</b></div><div><span>Mol-mulk</span><b>${finMoney(s.propertyTax)}</b></div><div><span>Boshqa soliq</span><b>${finMoney(s.otherTax)}</b></div></div><hr style="border:0;border-top:1px solid #e4ece8;margin:14px 0"><div class="fin-total-box"><div><span>Jami hisoblangan</span><b>${finMoney(s.taxAccrued)}</b></div><div><span>To‘langan</span><b>${finMoney(s.taxPaid)}</b></div><div><span>Soliq qarzi</span><b>${finMoney(s.taxDebt)}</b></div><div><span>Sotuv bazasi</span><b>${finMoney(s.revenue)}</b></div></div><div class="fin-form" style="margin-top:14px"><label>Soliq turi<select id="taxType"><option>Savdo aylanmasi solig‘i</option><option>JShDS / Oylik solig‘i</option><option>Ijtimoiy soliq</option><option>Yer solig‘i</option><option>Mol-mulk solig‘i</option><option>Boshqa soliq</option></select></label><label>To‘lov summa<input id="taxAmount" type="number"></label><label>Sana<input id="taxDate" type="date" value="${today}"></label><label>Hisob<select id="taxAccount"><option value="bank">Bank</option><option value="cash">Kassa</option></select></label><button class="btn primary wide" onclick="addTaxPayment()">Soliq to‘lovini kiritish</button></div></div></div></div>`}
function renderFinanceExpenses(){const expenses=FIN.expenses||[],today=new Date().toISOString().slice(0,10);return `<div class="fin-pane"><div class="fin-grid2"><div class="fin-card"><h3>Boshqa xarajat kiritish</h3><div class="fin-form"><label>Nomi<input id="expName" placeholder="Yo‘l kira, ijara..."></label><label>Kategoriya<select id="expCategory"><option>Yo‘l kira</option><option>Ijara</option><option>Kommunal</option><option>Reklama</option><option>Bank xarajati</option><option>Transport</option><option>Boshqa</option></select></label><label>Summa<input id="expAmount" type="number"></label><label>Sana<input id="expDate" type="date" value="${today}"></label><label>Hisob<select id="expAccount"><option value="bank">Bank</option><option value="cash">Kassa</option></select></label><label>Izoh<input id="expNote"></label><button class="btn primary wide" onclick="addExpense()">Xarajatni saqlash</button></div></div><div class="fin-card"><h3>Xarajatlar jurnali</h3><div class="fin-table"><table><thead><tr><th>Sana</th><th>Nomi</th><th>Kategoriya</th><th>Summa</th><th>Hisob</th></tr></thead><tbody>${expenses.slice(0,200).map(x=>`<tr><td>${esc(x.date||'')}</td><td><b>${esc(x.name||'')}</b></td><td>${esc(x.category||'')}</td><td>${finMoney(x.amount)}</td><td>${x.account==='cash'?'Kassa':'Bank'}</td></tr>`).join('')||'<tr><td colspan="5" class="fin-empty">Xarajat yo‘q</td></tr>'}</tbody></table></div></div></div></div>`}
function renderFinanceReports(){const b=FIN.balance||{},s=FIN.summary||{},month=$('#finMonth')?.value||new Date().toISOString().slice(0,7),year=$('#finYear')?.value||new Date().getFullYear();return `<div class="fin-pane"><div class="fin-card"><h3>Yagona balans</h3><div class="fin-balance"><div><span>Kassa</span><b>${finMoney(b.cash)}</b></div><div><span>Bank</span><b>${finMoney(b.bank)}</b></div><div><span>Ombor qiymati</span><b>${finMoney(b.inventoryValue)}</b></div><div><span>Firmalarga qarz</span><b>${finMoney(b.supplierDebt)}</b></div><div><span>Ish haqi qarzi</span><b>${finMoney(b.payrollDebt)}</b></div><div><span>Soliq qarzi</span><b>${finMoney(b.taxDebt)}</b></div><div><span>Aktivlar</span><b>${finMoney(b.assets)}</b></div><div><span>Majburiyatlar</span><b>${finMoney(b.liabilities)}</b></div><div><span>Kapital / Netto</span><b>${finMoney(b.equity)}</b></div></div></div><div class="fin-grid2"><div class="fin-card"><h3>Oylik yakuniy Excel</h3><p class="fin-note">Sotuv, tannarx, foyda, soliqlar, ish haqi, xarajatlar, firmalar qarzdorligi va balans bir hisobotda.</p><a class="btn primary" href="/api/admin/finance-report.xls?period=monthly&value=${encodeURIComponent(month)}">${esc(month)} — Excel yuklash</a></div><div class="fin-card"><h3>Yillik / Годовой Excel</h3><p class="fin-note">12 oyning moliyaviy natijalari va yil yakuniy balansi.</p><a class="btn primary" href="/api/admin/finance-report.xls?period=yearly&value=${encodeURIComponent(year)}">${esc(year)} — Yillik Excel yuklash</a></div></div><div class="fin-total-box"><div><span>Davr tushumi</span><b>${finMoney(s.revenue)}</b></div><div><span>Davr tannarxi</span><b>${finMoney(s.cogs)}</b></div><div><span>Davr soliqlari</span><b>${finMoney(s.taxAccrued)}</b></div><div><span>Sof natija</span><b>${finMoney(s.netProfit)}</b></div></div></div>`}
async function saveFinanceSettings(){try{await api('/api/admin/finance/settings',{method:'PUT',body:JSON.stringify({turnoverTaxRate:Number($('#fsTurn').value),payrollIncomeTaxRate:Number($('#fsPayrollIncome').value),payrollPensionRate:Number($('#fsPension').value),payrollBudgetShareRate:Number($('#fsBudgetShare').value),employerSocialTaxRate:Number($('#fsSocial').value),landTaxMonthly:Number($('#fsLand').value),propertyTaxBase:Number($('#fsPropBase').value),propertyTaxRate:Number($('#fsPropRate').value),otherTaxRate:Number($('#fsOtherRate').value),otherTaxBase:$('#fsOtherBase').value,otherTaxMonthly:Number($('#fsOtherMonthly').value),defaultMarkupRate:Number($('#fsMarkup').value),defaultSalesAccount:$('#fsSalesAcc').value,cashOpening:Number($('#fsCash').value),bankOpening:Number($('#fsBank').value)})});await loadFinance();alert('Finans sozlamalari saqlandi')}catch(e){alert(e.message)}}
async function addFinanceCompany(){try{await api('/api/admin/finance/companies',{method:'POST',body:JSON.stringify({name:$('#coName').value,inn:$('#coInn').value,phone:$('#coPhone').value,note:$('#coNote').value})});await loadFinance()}catch(e){alert(e.message)}}
async function addCompanyPayment(){try{await api('/api/admin/finance/company-payments',{method:'POST',body:JSON.stringify({companyId:$('#payCompany').value,amount:Number($('#payCompanyAmount').value),date:$('#payCompanyDate').value,account:$('#payCompanyAccount').value,note:$('#payCompanyNote').value})});await loadFinance()}catch(e){alert(e.message)}}
async function addFinancePurchase(){try{const r=await api('/api/admin/finance/purchases',{method:'POST',body:JSON.stringify({companyId:$('#purCompany').value,productId:Number($('#purProduct').value),qty:Number($('#purQty').value),unitCost:Number($('#purUnitCost').value),transport:Number($('#purTransport').value),extra:Number($('#purExtra').value),paidAmount:Number($('#purPaid').value),markupRate:Number($('#purMarkup').value),salePrice:Number($('#purSalePrice').value),date:$('#purDate').value,invoice:$('#purInvoice').value,account:$('#purAccount').value,note:$('#purNote').value})});alert(`Prixod saqlandi. Yangi qoldiq: ${r.stock}. Sotuv narxi: ${finMoney(r.salePrice)}`);await loadFinance()}catch(e){alert(e.message)}}
async function addEmployee(){try{await api('/api/admin/finance/employees',{method:'POST',body:JSON.stringify({name:$('#empName').value,position:$('#empPosition').value,salary:Number($('#empSalary').value),phone:$('#empPhone').value,startedAt:$('#empStarted').value})});await loadFinance()}catch(e){alert(e.message)}}
async function editEmployee(id){const e=(FIN.employees||[]).find(x=>String(x.id)===String(id));if(!e)return;const name=prompt('F.I.Sh.',e.name);if(name===null)return;const position=prompt('Lavozim',e.position||'');if(position===null)return;const salary=prompt('Oylik',String(e.salary||0));if(salary===null)return;const phone=prompt('Telefon',e.phone||'');if(phone===null)return;try{await api('/api/admin/finance/employees/'+encodeURIComponent(id),{method:'PATCH',body:JSON.stringify({name,position,salary:Number(salary),phone})});await loadFinance()}catch(err){alert(err.message)}}
async function toggleEmployee(id,active){const msg=active?'Ishchini qayta faollashtirasizmi?':'Ishchini ishdan bo‘shagan sifatida belgilaysizmi? Oldingi oylik tarixi saqlanadi.';if(!confirm(msg))return;try{await api('/api/admin/finance/employees/'+encodeURIComponent(id),{method:'PATCH',body:JSON.stringify({active})});await loadFinance()}catch(e){alert(e.message)}}
async function deleteEmployee(id){if(!confirm('Ishchini butunlay o‘chirishga urinamizmi? Oylik tarixi bo‘lsa tizim o‘chirishga ruxsat bermaydi.'))return;try{await api('/api/admin/finance/employees/'+encodeURIComponent(id),{method:'DELETE'});await loadFinance()}catch(e){alert(e.message)}}
async function generatePayroll(){try{await api('/api/admin/finance/payroll/generate',{method:'POST',body:JSON.stringify({month:$('#payrollMonth').value})});await loadFinance()}catch(e){alert(e.message)}}
async function savePayroll(id){try{await api('/api/admin/finance/payroll/'+encodeURIComponent(id),{method:'PATCH',body:JSON.stringify({bonus:Number($(`#pb-${id}`).value),advance:Number($(`#pa-${id}`).value),deduction:Number($(`#pd-${id}`).value),paid:Number($(`#pp-${id}`).value),account:'bank'})});await loadFinance()}catch(e){alert(e.message)}}
async function addExpense(){try{await api('/api/admin/finance/expenses',{method:'POST',body:JSON.stringify({name:$('#expName').value,category:$('#expCategory').value,amount:Number($('#expAmount').value),date:$('#expDate').value,account:$('#expAccount').value,note:$('#expNote').value})});await loadFinance()}catch(e){alert(e.message)}}
async function addTaxPayment(){try{await api('/api/admin/finance/tax-payments',{method:'POST',body:JSON.stringify({type:$('#taxType').value,amount:Number($('#taxAmount').value),date:$('#taxDate').value,account:$('#taxAccount').value})});await loadFinance()}catch(e){alert(e.message)}}
function downloadReconciliation(){const companyId=$('#reconCompany')?.value;if(!companyId){alert('Firma tanlang');return}window.location=`/api/admin/finance/reconciliation.xls?companyId=${encodeURIComponent(companyId)}&from=${encodeURIComponent($('#reconFrom')?.value||'')}&to=${encodeURIComponent($('#reconTo')?.value||'')}`}

function promosPane(){return `<div class="panel"><div class="toolbar"><button class="btn primary sm" onclick="addPromo()">+ Promo kod</button><button class="btn ghost sm" onclick="savePromos()">Saqlash</button></div><div id="promoList">${D.promos.map((p,i)=>promoRow(p,i)).join('')}</div></div>`}
function promoRow(p,i){return `<div class="promo-row" data-i="${i}"><input class="code" value="${esc(p.code)}" placeholder="KOD"><select class="type"><option value="percent" ${p.type==='percent'?'selected':''}>%</option><option value="fixed" ${p.type==='fixed'?'selected':''}>So‘m</option></select><input class="value" type="number" value="${p.value}" placeholder="Qiymat"><input class="min" type="number" value="${p.minTotal||0}" placeholder="Min summa"><input class="limit" type="number" value="${p.usageLimit||0}" placeholder="Limit"><input class="expires" type="date" value="${esc(p.expires||'')}"><select class="active"><option value="1" ${p.active?'selected':''}>Faol</option><option value="0" ${!p.active?'selected':''}>O‘chiq</option></select><button class="btn danger sm" onclick="removePromo(${i})">×</button></div>`}
function addPromo(){D.promos.push({code:'YANGI10',type:'percent',value:10,minTotal:0,active:true,usageLimit:100,used:0,expires:''});renderPane()}
function removePromo(i){D.promos.splice(i,1);renderPane()}
async function savePromos(){document.querySelectorAll('.promo-row').forEach(r=>{const p=D.promos[Number(r.dataset.i)];p.code=r.querySelector('.code').value.toUpperCase();p.type=r.querySelector('.type').value;p.value=Number(r.querySelector('.value').value);p.minTotal=Number(r.querySelector('.min').value);p.usageLimit=Number(r.querySelector('.limit').value);p.expires=r.querySelector('.expires').value;p.active=r.querySelector('.active').value==='1'});try{await api('/api/admin/promos',{method:'PUT',body:JSON.stringify({promos:D.promos})});alert('Promo kodlar saqlandi');await refresh()}catch(e){alert(e.message)}}
function areasPane(){return `<div class="panel area-editor"><h3>Parkent tumani yetkazib berish hududlari</h3><p class="muted">Har bir hududni alohida qatorda yozing. Mijoz checkoutda shu ro‘yxatdan majburiy tanlaydi. Yetkazib berish bepul.</p><textarea id="areasText">${esc((D.settings.delivery?.areas||[]).join('\n'))}</textarea><h3>Yetkazish vaqt oralig‘i</h3><textarea id="slotsText" style="min-height:120px">${esc((D.settings.delivery?.slots||[]).join('\n'))}</textarea><button class="btn primary" onclick="saveAreas()">Hududlarni saqlash</button></div>`}
async function saveAreas(){D.settings.delivery=D.settings.delivery||{};D.settings.delivery.free=true;D.settings.delivery.district='Parkent tumani';D.settings.delivery.areas=$('#areasText').value.split('\n').map(x=>x.trim()).filter(Boolean);D.settings.delivery.slots=$('#slotsText').value.split('\n').map(x=>x.trim()).filter(Boolean);await saveSettings('Hududlar saqlandi')}

function slidesPane(){const slides=Array.isArray(D.settings.heroSlides)?D.settings.heroSlides:[];return `<div class="panel"><div class="slider-admin-head"><div><h2 style="margin:0">Bosh sahifa slayderi</h2><p class="muted">Parkent tabiatini ko‘rsatish uchun maksimum 5 ta rasm. Rasmlar saytning yuqori qismida avtomatik almashib turadi.</p></div>${slides.length<5?`<label class="btn primary slider-upload-btn">+ Yangi rasm qo‘shish<input type="file" accept="image/jpeg,image/png,image/webp" onchange="addHeroSlide(event)"></label>`:''}</div><div class="slider-admin-grid">${slides.length?slides.map((x,i)=>`<div class="slider-admin-row"><div class="slide-order">${i+1}</div><img class="slider-admin-preview" src="${esc(x.image)}" alt="Slayd ${i+1}"><div class="slider-admin-info"><b>Slayd ${i+1}</b><span class="muted">${x.active===false?'O‘chirilgan':'Faol'}</span><div class="slider-admin-actions"><label class="btn ghost sm slider-upload-btn">Rasmni almashtirish<input type="file" accept="image/jpeg,image/png,image/webp" onchange="replaceHeroSlide(event,${i})"></label><button class="btn ghost sm" type="button" onclick="moveHeroSlide(${i},-1)" ${i===0?'disabled':''}>↑</button><button class="btn ghost sm" type="button" onclick="moveHeroSlide(${i},1)" ${i===slides.length-1?'disabled':''}>↓</button><button class="btn ghost sm" type="button" onclick="toggleHeroSlide(${i})">${x.active===false?'Faollashtirish':'O‘chirish'}</button></div></div><button class="btn danger sm" type="button" onclick="removeHeroSlide(${i})">Olib tashlash</button></div>`).join(''):`<div class="slide-empty"><b>Hozircha slayd yo‘q.</b><br>Yuqoridagi “Yangi rasm qo‘shish” orqali rasm yuklang.</div>`}</div><div class="notice slider-tip"><b>Tavsiya:</b> gorizontal rasm ishlating (taxminan 1920×600 yoki 1600×500). JPG, PNG, WEBP. Maksimum 5 ta. Saytda har 5 soniyada navbat bilan almashadi.</div><div class="pages-savebar"><button class="btn primary" onclick="saveHeroSlides()">Slayderni saqlash</button></div></div>`}
function optimizeSlideFile(file,cb){if(!file)return;if(!/^image\/(jpeg|png|webp)$/.test(file.type)){alert('Faqat JPG, PNG yoki WEBP rasm tanlang.');return}if(file.size>12*1024*1024){alert('Rasm 12 MB dan katta bo‘lmasin.');return}const img=new Image(),reader=new FileReader();reader.onload=()=>{img.onload=()=>{const maxW=1920,maxH=900,scale=Math.min(1,maxW/img.width,maxH/img.height),w=Math.max(1,Math.round(img.width*scale)),h=Math.max(1,Math.round(img.height*scale)),c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(img,0,0,w,h);let data;try{data=c.toDataURL('image/webp',.86)}catch{data=c.toDataURL('image/jpeg',.88)};cb(data)};img.src=reader.result};reader.readAsDataURL(file)}
function addHeroSlide(e){const f=e.target.files?.[0];if(!f)return;D.settings.heroSlides=Array.isArray(D.settings.heroSlides)?D.settings.heroSlides:[];if(D.settings.heroSlides.length>=5){alert('Maksimum 5 ta rasm mumkin.');return}optimizeSlideFile(f,data=>{D.settings.heroSlides.push({id:'slide-'+Date.now(),image:data,active:true});renderPane()})}
function replaceHeroSlide(e,i){const f=e.target.files?.[0];if(!f)return;optimizeSlideFile(f,data=>{D.settings.heroSlides[i].image=data;renderPane()})}
function removeHeroSlide(i){if(!confirm('Bu slayd olib tashlansinmi?'))return;D.settings.heroSlides.splice(i,1);renderPane()}
function moveHeroSlide(i,d){const a=D.settings.heroSlides,j=i+d;if(j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];renderPane()}
function toggleHeroSlide(i){D.settings.heroSlides[i].active=D.settings.heroSlides[i].active===false?true:false;renderPane()}
async function saveHeroSlides(){await saveSettings('Bosh sahifa slayderi saqlandi')}

function pagesPane(){const s=D.settings,co=s.company||{},mp=s.map||{},ft=s.footer||{},cu=s.catalogUi||{},ui=s.ui||{},tm=s.testMode||{};return `<div class="panel"><div class="full-editor-note"><b>To‘liq sahifa muharriri.</b> Bu yerda sayt logotipi, matnlar, rekvizitlar, xarita, aloqa, footer va SEO ma’lumotlarini o‘zgartirishingiz mumkin.</div><div class="form-grid">
<h3 class="wide">Logotip va brend</h3><div class="wide logo-editor"><div>${D.logo?`<img src="${D.logo}" alt="Logo">`:`<img src="logo.png" alt="Logo">`}</div><div><h3>Sayt logotipi</h3><p class="muted">JPG, PNG yoki WEBP. Rasm avtomatik optimallashtiriladi.</p><div class="logo-actions"><label class="btn primary sm">Logotip tanlash<input type="file" accept="image/jpeg,image/png,image/webp" hidden onchange="setSiteLogo(event)"></label>${D.logo?`<button class="btn danger sm" type="button" onclick="removeSiteLogo()">Yuklangan logoni olib tashlash</button>`:''}</div></div></div>
<label>Sayt nomi<input id="siteName" value="${esc(s.siteName||'')}"></label><label>Domen<input id="siteDomain" value="${esc(s.siteDomain||'')}"></label><label>Dizayn<select id="theme"><option value="original" ${s.theme==='original'?'selected':''}>Original</option><option value="modern" ${s.theme==='modern'?'selected':''}>Modern</option><option value="classic" ${s.theme==='classic'?'selected':''}>Classic</option></select></label><label>Logotip o‘lchami (48–100 px)<input id="logoSize" type="number" min="48" max="100" value="${Number(ui.logoSize||68)}"></label><label>Telefon<input id="phone" value="${esc(s.phone||'')}"></label><label>Telegram<input id="telegram" value="${esc(s.telegram||'')}"></label><label>Email<input id="email" value="${esc(s.email||'')}"></label>
<h3 class="wide section-card">Test rejimi yozuvi</h3><div class="wide test-toggle-box"><input id="testModeActive" type="checkbox" ${tm.active===false?'':'checked'}><label for="testModeActive"><b>Sayt tepasida test rejimi yozuvini ko‘rsatish</b><br><span class="muted">Belgini olib tashlasangiz yozuv saytdan yo‘qoladi.</span></label></div><label class="wide">Test rejimi matni<input id="testModeText" value="${esc(tm.text||'Saytimiz hozirda test rejimida ishlamoqda')}"></label>
<h3 class="wide section-card">Teglayn / yuqori yozuvlar</h3><label class="wide">Teglayn UZ<input id="tagUz" value="${esc(s.tagline?.uz||'')}"></label><label>Teglayn RU<input id="tagRu" value="${esc(s.tagline?.ru||'')}"></label>
<h3 class="wide section-card">Katalog</h3><label>Katalog ustki yozuvi<input id="catalogEyebrowEdit" value="${esc(cu.eyebrow||'SARALANGAN KATALOG')}"></label><label>Tavsiya tugmasi<input id="sortFeaturedEdit" value="${esc(cu.featured||'Tavsiya etiladi')}"></label><label>Arzon tugmasi<input id="sortAscEdit" value="${esc(cu.priceAsc||'Narx: arzon')}"></label><label>Qimmat tugmasi<input id="sortDescEdit" value="${esc(cu.priceDesc||'Narx: qimmat')}"></label><label>Yangi tugmasi<input id="sortNewEdit" value="${esc(cu.newLabel||'Yangi')}"></label>
<h3 class="wide section-card">Biz haqimizda</h3><label class="wide">Sarlavha<input id="aboutTitle" value="${esc(s.about?.uz?.title||'')}"></label><label class="wide">Matn<textarea id="aboutText">${esc(s.about?.uz?.text||'')}</textarea></label>
<h3 class="wide section-card">Korxona rekvizitlari</h3><label class="wide">Firma nomi<input id="companyNameEdit" value="${esc(co.name||'')}"></label><label>STIR (INN)<input id="companyTaxEdit" value="${esc(co.taxId||'')}"></label><label>Bank kodi (MFO)<input id="companyMfoEdit" value="${esc(co.mfo||'')}"></label><label class="wide">Hisob raqami<input id="companyAccountEdit" value="${esc(co.account||'')}"></label>
<h3 class="wide section-card">Parkent xaritasi</h3><label class="wide">Ustki yozuv<input id="mapEyebrowEdit" value="${esc(mp.eyebrow||'')}"></label><label class="wide">Sarlavha<input id="mapTitleEdit" value="${esc(mp.title||'')}"></label><label class="wide">Matn<textarea id="mapTextEdit">${esc(mp.text||'')}</textarea></label><label class="wide">Xarita iframe manzili<input id="mapEmbedEdit" value="${esc(mp.embedUrl||'')}"></label><label class="wide">Katta xarita havolasi<input id="mapOpenEdit" value="${esc(mp.openUrl||'')}"></label>
<h3 class="wide section-card">Aloqa</h3><label class="wide">Sarlavha<input id="contactTitle" value="${esc(s.contact?.uz?.title||'')}"></label><label class="wide">Matn<textarea id="contactText">${esc(s.contact?.uz?.text||'')}</textarea></label>
<h3 class="wide section-card">Footer</h3><label>1-xizmat yozuvi<input id="footerService1Edit" value="${esc(ft.service1||'')}"></label><label>2-xizmat yozuvi<input id="footerService2Edit" value="${esc(ft.service2||'')}"></label><label class="wide">Copyright<input id="copyrightEdit" value="${esc(ft.copyright||'')}"></label>
<h3 class="wide section-card">SEO</h3><label class="wide">Meta title<input id="seoTitle" value="${esc(s.seo?.title||'')}"></label><label class="wide">Meta description<textarea id="seoDesc">${esc(s.seo?.description||'')}</textarea></label><label class="wide">Keywords<input id="seoKeywords" value="${esc(s.seo?.keywords||'')}"></label></div><div class="pages-savebar"><button class="btn primary" onclick="savePages()">Barcha sahifa sozlamalarini saqlash</button></div></div>`}
function setSiteLogo(e){const file=e.target.files?.[0];if(!file)return;if(!/^image\/(jpeg|png|webp)$/.test(file.type)){alert('Faqat JPG, PNG yoki WEBP rasm tanlang.');return}if(file.size>8*1024*1024){alert('Rasm 8 MB dan katta bo‘lmasin.');return}const img=new Image(),reader=new FileReader();reader.onload=()=>{img.onload=()=>{const max=1200,scale=Math.min(1,max/Math.max(img.width,img.height)),w=Math.max(1,Math.round(img.width*scale)),h=Math.max(1,Math.round(img.height*scale)),c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(img,0,0,w,h);try{D.logo=c.toDataURL('image/webp',.9)}catch{D.logo=c.toDataURL('image/jpeg',.9)};renderPane()};img.src=reader.result};reader.readAsDataURL(file)}
function removeSiteLogo(){if(!confirm('Yuklangan logotip olib tashlansinmi? Standart logo qaytadi.'))return;D.logo='';renderPane()}
async function savePages(){const s=D.settings;s.siteName=$('#siteName').value.trim();s.siteDomain=$('#siteDomain').value.trim();s.theme=$('#theme').value;s.phone=$('#phone').value.trim();s.telegram=$('#telegram').value.trim();s.email=$('#email').value.trim();s.ui=s.ui||{};s.ui.logoSize=Math.max(48,Math.min(100,Number($('#logoSize').value)||68));s.testMode=s.testMode||{};s.testMode.active=$('#testModeActive').checked;s.testMode.text=$('#testModeText').value.trim()||'Saytimiz hozirda test rejimida ishlamoqda';s.tagline=s.tagline||{};s.tagline.uz=$('#tagUz').value;s.tagline.ru=$('#tagRu').value;s.catalogUi=s.catalogUi||{};s.catalogUi.eyebrow=$('#catalogEyebrowEdit').value;s.catalogUi.featured=$('#sortFeaturedEdit').value;s.catalogUi.priceAsc=$('#sortAscEdit').value;s.catalogUi.priceDesc=$('#sortDescEdit').value;s.catalogUi.newLabel=$('#sortNewEdit').value;s.about=s.about||{};s.about.uz=s.about.uz||{};s.about.uz.title=$('#aboutTitle').value;s.about.uz.text=$('#aboutText').value;s.company=s.company||{};s.company.name=$('#companyNameEdit').value;s.company.taxId=$('#companyTaxEdit').value;s.company.mfo=$('#companyMfoEdit').value;s.company.account=$('#companyAccountEdit').value;s.map=s.map||{};s.map.eyebrow=$('#mapEyebrowEdit').value;s.map.title=$('#mapTitleEdit').value;s.map.text=$('#mapTextEdit').value;s.map.embedUrl=$('#mapEmbedEdit').value;s.map.openUrl=$('#mapOpenEdit').value;s.contact=s.contact||{};s.contact.uz=s.contact.uz||{};s.contact.uz.title=$('#contactTitle').value;s.contact.uz.text=$('#contactText').value;s.footer=s.footer||{};s.footer.service1=$('#footerService1Edit').value;s.footer.service2=$('#footerService2Edit').value;s.footer.copyright=$('#copyrightEdit').value;s.seo=s.seo||{};s.seo.title=$('#seoTitle').value;s.seo.description=$('#seoDesc').value;s.seo.keywords=$('#seoKeywords').value;await saveSettings('Barcha sahifa sozlamalari saqlandi')}
async function saveSettings(msg){try{await api('/api/admin/catalog',{method:'PUT',body:JSON.stringify({products:D.products,categories:D.categories,settings:D.settings,logo:D.logo})});alert(msg);await refresh()}catch(e){alert(e.message)}}
function auditPane(){return `<div class="panel"><div class="toolbar"><a class="btn primary sm" href="/api/admin/backup.json">Backup yuklash</a><label class="btn ghost sm">Backup tiklash<input id="restoreFile" type="file" accept="application/json" hidden onchange="restoreBackup(event)"></label></div><div class="notice">Audit log admin, operator, Telegram va mijoz tomonidan bajarilgan asosiy harakatlarni qayd qiladi.</div><div class="audit-list">${D.audit.map(a=>`<div class="audit-item"><span>${new Date(a.at).toLocaleString('uz-UZ')}</span><b>${esc(a.user)}</b><span>${esc(a.action)}</span><span>${esc(a.details)}</span></div>`).join('')}</div></div>`}
async function restoreBackup(e){const f=e.target.files[0];if(!f)return;if(!confirm('Backupni tiklash joriy ma’lumotlarni almashtiradi. Davom etasizmi?'))return;try{const txt=await f.text();const data=JSON.parse(txt);await api('/api/admin/restore',{method:'POST',body:JSON.stringify(data)});alert('Backup tiklandi');await refresh()}catch(err){alert(err.message)}}
initAdminRealtime();
boot();
